const presets = {
  binary: [
    { id: "equalBinary", masses: [1, 1], separation: 1.4 },
    { id: "unequalBinary", masses: [1.4, 0.45], separation: 1.6 }
  ],
  triple: [
    { id: "figureEight", masses: [1, 1, 1], figureEight: true },
    { id: "hierarchicalTriple", masses: [1, 0.8, 0.35], hierarchical: true }
  ]
};
const colors = ["#ffd166", "#72c7ff", "#ff8c9a"];
const canvas = document.getElementById("star-canvas");
const context = canvas.getContext("2d");
const languageButton = document.getElementById("language-button");
const systemSelect = document.getElementById("system-type");
const presetSelect = document.getElementById("system-preset");
const playButton = document.getElementById("play-toggle");
const resetButton = document.getElementById("reset-button");
const speedControl = document.getElementById("speed-control");
const speedValue = document.getElementById("speed-value");
const gravityVectorsToggle = document.getElementById("show-gravity-vectors");
const massControls = document.getElementById("mass-controls");
const savedLanguage = localStorage.getItem("universe-language");
let currentLanguage = translations[savedLanguage] ? savedLanguage : "en";
let stars = [];
let trails = [];
let elapsed = 0;
let paused = window.matchMedia("(prefers-reduced-motion: reduce)").matches;
let previousFrame = 0;
let descriptionTimer = 0;

function applyLanguage() {
  const text = translations[currentLanguage];
  document.documentElement.lang = currentLanguage;
  document.title = text.title;
  document.querySelectorAll("[data-i18n]").forEach((element) => {
    element.textContent = text[element.dataset.i18n];
  });
  document.querySelectorAll("[data-i18n-aria-label]").forEach((element) => {
    element.setAttribute("aria-label", text[element.dataset.i18nAriaLabel]);
  });
  languageButton.textContent = currentLanguage === "en" ? "中文" : "English";
  languageButton.setAttribute("aria-label", text.changeLanguage);
  renderPresetOptions();
  renderMassControls();
  renderLegend();
  updateStats();
  updateControls();
  updateCanvasDescription();
}

function renderPresetOptions() {
  const text = translations[currentLanguage];
  const options = presets[systemSelect.value];
  const selectedPreset = options.some((preset) => preset.id === presetSelect.value)
    ? presetSelect.value
    : options[0].id;
  presetSelect.innerHTML = options.map((preset) =>
    `<option value="${preset.id}">${text[preset.id]}</option>`
  ).join("");
  presetSelect.value = selectedPreset;
}

function makeStars(preset) {
  const masses = preset.masses;
  if (preset.figureEight) {
    return [
      { x: -0.97000436, y: 0.24308753, vx: 0.466203685, vy: 0.43236573 },
      { x: 0.97000436, y: -0.24308753, vx: 0.466203685, vy: 0.43236573 },
      { x: 0, y: 0, vx: -0.93240737, vy: -0.86473146 }
    ].map((star, index) => ({ ...star, mass: masses[index], color: colors[index] }));
  }

  if (preset.hierarchical) {
    const innerMass = masses[0] + masses[1];
    const outerMass = masses[2];
    const outerPericenter = 1.75;
    const outerEccentricity = 0.22;
    const innerCenterX = -outerMass * outerPericenter / (innerMass + outerMass);
    const outerX = innerMass * outerPericenter / (innerMass + outerMass);
    const innerSeparation = 0.72;
    const innerSpeed = Math.sqrt(innerMass / innerSeparation);
    const outerSpeed = Math.sqrt((innerMass + outerMass) * (1 + outerEccentricity) / outerPericenter);
    const innerCenterVelocityY = -outerMass * outerSpeed / (innerMass + outerMass);
    const outerVelocityY = innerMass * outerSpeed / (innerMass + outerMass);
    return [
      { x: innerCenterX - masses[1] * innerSeparation / innerMass, y: 0, vx: 0, vy: innerCenterVelocityY - masses[1] * innerSpeed / innerMass },
      { x: innerCenterX + masses[0] * innerSeparation / innerMass, y: 0, vx: 0, vy: innerCenterVelocityY + masses[0] * innerSpeed / innerMass },
      { x: outerX, y: 0, vx: 0, vy: outerVelocityY }
    ].map((star, index) => ({ ...star, mass: masses[index], color: colors[index] }));
  }

  const separation = preset.separation;
  const totalMass = masses[0] + masses[1];
  const relativeSpeed = Math.sqrt(totalMass / separation);
  return [
    { x: -masses[1] * separation / totalMass, y: 0, vx: 0, vy: -masses[1] * relativeSpeed / totalMass },
    { x: masses[0] * separation / totalMass, y: 0, vx: 0, vy: masses[0] * relativeSpeed / totalMass }
  ].map((star, index) => ({ ...star, mass: masses[index], color: colors[index] }));
}

function resetSimulation() {
  const preset = presets[systemSelect.value].find((item) => item.id === presetSelect.value);
  stars = makeStars(preset);
  trails = stars.map(() => []);
  elapsed = 0;
  renderMassControls();
  renderLegend();
  updateStats();
  updateCanvasDescription();
  draw(true);
}

function renderMassControls() {
  const text = translations[currentLanguage];
  massControls.innerHTML = stars.map((star, index) => `
    <label class="mass-control" for="mass-slider-${index}">
      <span class="mass-control-label"><i style="--star-color:${star.color}" aria-hidden="true"></i>${text.star} ${index + 1} <output id="mass-value-${index}" for="mass-slider-${index}">${star.mass.toFixed(2)} M</output></span>
      <input id="mass-slider-${index}" data-star-index="${index}" type="range" min="0.10" max="2.50" step="0.05" value="${star.mass}" aria-label="${text.star} ${index + 1} ${text.starMassLabel}">
    </label>
  `).join("");
}

function calculateAccelerations(state) {
  const acceleration = state.map(() => ({ x: 0, y: 0 }));
  for (let i = 0; i < state.length; i += 1) {
    for (let j = i + 1; j < state.length; j += 1) {
      const dx = state[j].x - state[i].x;
      const dy = state[j].y - state[i].y;
      const distanceSquared = dx * dx + dy * dy + 0.0001;
      const inverseDistanceCubed = 1 / (distanceSquared * Math.sqrt(distanceSquared));
      acceleration[i].x += state[j].mass * dx * inverseDistanceCubed;
      acceleration[i].y += state[j].mass * dy * inverseDistanceCubed;
      acceleration[j].x -= state[i].mass * dx * inverseDistanceCubed;
      acceleration[j].y -= state[i].mass * dy * inverseDistanceCubed;
    }
  }
  return acceleration;
}

function derivative(state) {
  const acceleration = calculateAccelerations(state);
  return state.map((star, index) => ({
    x: star.vx, y: star.vy,
    vx: acceleration[index].x, vy: acceleration[index].y
  }));
}

function offsetState(state, change, amount) {
  return state.map((star, index) => ({
    ...star,
    x: star.x + change[index].x * amount,
    y: star.y + change[index].y * amount,
    vx: star.vx + change[index].vx * amount,
    vy: star.vy + change[index].vy * amount
  }));
}

function advance(dt) {
  const k1 = derivative(stars);
  const k2 = derivative(offsetState(stars, k1, dt / 2));
  const k3 = derivative(offsetState(stars, k2, dt / 2));
  const k4 = derivative(offsetState(stars, k3, dt));
  stars = stars.map((star, index) => ({
    ...star,
    x: star.x + dt * (k1[index].x + 2 * k2[index].x + 2 * k3[index].x + k4[index].x) / 6,
    y: star.y + dt * (k1[index].y + 2 * k2[index].y + 2 * k3[index].y + k4[index].y) / 6,
    vx: star.vx + dt * (k1[index].vx + 2 * k2[index].vx + 2 * k3[index].vx + k4[index].vx) / 6,
    vy: star.vy + dt * (k1[index].vy + 2 * k2[index].vy + 2 * k3[index].vy + k4[index].vy) / 6
  }));
  elapsed += dt;
}

function draw(recordTrail = false) {
  const width = canvas.clientWidth;
  const height = canvas.clientHeight;
  if (!width || !height || !stars.length) return;
  const pixelRatio = window.devicePixelRatio || 1;
  const targetWidth = Math.round(width * pixelRatio);
  const targetHeight = Math.round(height * pixelRatio);
  if (canvas.width !== targetWidth || canvas.height !== targetHeight) {
    canvas.width = targetWidth;
    canvas.height = targetHeight;
  }
  context.setTransform(pixelRatio, 0, 0, pixelRatio, 0, 0);
  context.clearRect(0, 0, width, height);

  const scale = Math.min(width / 5.2, height / 3.4);
  const centerX = width / 2;
  const centerY = height / 2;
  const barycenter = stars.reduce((sum, star) => ({
    x: sum.x + star.x * star.mass,
    y: sum.y + star.y * star.mass
  }), { x: 0, y: 0 });
  barycenter.x /= stars.reduce((sum, star) => sum + star.mass, 0);
  barycenter.y /= stars.reduce((sum, star) => sum + star.mass, 0);

  trails.forEach((trail, index) => {
    const star = stars[index];
    if (recordTrail) trail.push({ x: star.x, y: star.y });
    if (trail.length > 650) trail.shift();
    if (trail.length < 2) return;
    context.beginPath();
    trail.forEach((point, pointIndex) => {
      const x = centerX + (point.x - barycenter.x) * scale;
      const y = centerY - (point.y - barycenter.y) * scale;
      if (pointIndex === 0) context.moveTo(x, y);
      else context.lineTo(x, y);
    });
    context.strokeStyle = `${star.color}78`;
    context.lineWidth = 1.5;
    context.stroke();
  });

  if (gravityVectorsToggle.checked) {
    const accelerations = calculateAccelerations(stars);
    accelerations.forEach((acceleration, index) => {
      const star = stars[index];
      const magnitude = Math.hypot(acceleration.x, acceleration.y);
      if (!magnitude) return;
      const arrowLength = Math.min(42, Math.max(12, Math.log1p(magnitude) * 24));
      const startX = centerX + (star.x - barycenter.x) * scale;
      const startY = centerY - (star.y - barycenter.y) * scale;
      const directionX = acceleration.x / magnitude;
      const directionY = -acceleration.y / magnitude;
      const endX = startX + directionX * arrowLength;
      const endY = startY + directionY * arrowLength;
      const headLength = 8;

      context.save();
      context.strokeStyle = `${star.color}dd`;
      context.fillStyle = star.color;
      context.lineWidth = 2;
      context.beginPath();
      context.moveTo(startX, startY);
      context.lineTo(endX, endY);
      context.stroke();
      context.beginPath();
      context.moveTo(endX, endY);
      context.lineTo(endX - directionX * headLength - directionY * headLength * 0.55,
        endY - directionY * headLength + directionX * headLength * 0.55);
      context.lineTo(endX - directionX * headLength + directionY * headLength * 0.55,
        endY - directionY * headLength - directionX * headLength * 0.55);
      context.closePath();
      context.fill();
      context.restore();
    });
  }

  context.save();
  context.translate(centerX + (barycenter.x - barycenter.x) * scale, centerY);
  context.strokeStyle = "rgba(236, 245, 255, 0.9)";
  context.lineWidth = 1.5;
  context.beginPath();
  context.moveTo(-7, 0); context.lineTo(7, 0);
  context.moveTo(0, -7); context.lineTo(0, 7);
  context.stroke();
  context.restore();

  stars.forEach((star, index) => {
    const x = centerX + (star.x - barycenter.x) * scale;
    const y = centerY - (star.y - barycenter.y) * scale;
    const radius = 7 + Math.min(7, Math.sqrt(star.mass) * 3);
    const glow = context.createRadialGradient(x, y, 1, x, y, radius * 3.2);
    glow.addColorStop(0, `${star.color}cc`);
    glow.addColorStop(1, `${star.color}00`);
    context.fillStyle = glow;
    context.beginPath(); context.arc(x, y, radius * 3.2, 0, Math.PI * 2); context.fill();
    context.fillStyle = star.color;
    context.beginPath(); context.arc(x, y, radius, 0, Math.PI * 2); context.fill();
    context.fillStyle = "#07111f";
    context.font = "bold 10px Arial, sans-serif";
    context.textAlign = "center";
    context.textBaseline = "middle";
    context.fillText(String(index + 1), x, y);
  });
}

function renderLegend() {
  const text = translations[currentLanguage];
  document.getElementById("star-legend").innerHTML = stars.map((star, index) =>
    `<span class="star-legend-item"><i style="--star-color:${star.color}" aria-hidden="true"></i>${text.star} ${index + 1}<strong>${star.mass.toFixed(2)} M</strong></span>`
  ).join("");
}

function updateStats() {
  const locale = currentLanguage === "zh" ? "zh-CN" : "en-US";
  document.getElementById("elapsed-time").textContent = elapsed.toLocaleString(locale, { maximumFractionDigits: 2 });
  document.getElementById("total-mass").textContent = stars.reduce((sum, star) => sum + star.mass, 0).toLocaleString(locale, { maximumFractionDigits: 2 });
}

function updateCanvasDescription() {
  if (!stars.length) return;
  const text = translations[currentLanguage];
  document.getElementById("canvas-description").textContent =
    stars.length === 2 ? text.canvasBinary : text.canvasTriple;
}

function updateControls() {
  const text = translations[currentLanguage];
  playButton.textContent = paused ? text.play : text.pause;
  playButton.setAttribute("aria-pressed", String(paused));
  speedValue.textContent = `${Number(speedControl.value).toFixed(2).replace(/0$/, "")}×`;
}

function frame(timestamp) {
  const frameSeconds = previousFrame ? Math.min((timestamp - previousFrame) / 1000, 0.05) : 0;
  previousFrame = timestamp;
  if (!paused && frameSeconds > 0) {
    const step = frameSeconds * Number(speedControl.value) * 0.48;
    const substeps = Math.max(1, Math.ceil(step / 0.004));
    for (let index = 0; index < substeps; index += 1) advance(step / substeps);
    draw(true);
    if (timestamp - descriptionTimer > 500) {
      updateStats();
      descriptionTimer = timestamp;
    }
  }
  window.requestAnimationFrame(frame);
}

systemSelect.addEventListener("change", () => {
  renderPresetOptions();
  resetSimulation();
});
presetSelect.addEventListener("change", resetSimulation);
playButton.addEventListener("click", () => {
  paused = !paused;
  updateControls();
});
resetButton.addEventListener("click", resetSimulation);
speedControl.addEventListener("input", updateControls);
languageButton.addEventListener("click", () => {
  currentLanguage = currentLanguage === "en" ? "zh" : "en";
  localStorage.setItem("universe-language", currentLanguage);
  applyLanguage();
});
window.addEventListener("resize", draw);
gravityVectorsToggle.addEventListener("change", () => draw());
massControls.addEventListener("input", (event) => {
  const slider = event.target.closest("input[data-star-index]");
  if (!slider) return;
  const starIndex = Number(slider.dataset.starIndex);
  stars[starIndex].mass = Number(slider.value);
  document.getElementById(`mass-value-${starIndex}`).textContent = `${stars[starIndex].mass.toFixed(2)} M`;
  updateStats();
  renderLegend();
  draw();
});

systemSelect.value = "binary";
renderPresetOptions();
presetSelect.value = "equalBinary";
resetSimulation();
applyLanguage();
updateControls();
window.requestAnimationFrame(frame);

* {
  box-sizing: border-box;
}
body {
  margin: 0;
  min-height: 100vh;
  font-family: Arial, sans-serif;
  background-color: #080f1d;
  background-image:
    linear-gradient(180deg, rgba(5, 11, 24, 0.83), rgba(5, 11, 24, 0.91)),
    url("images/kepler-9-transit-concept.jpg");
  background-size: cover;
  background-position: center 24%;
  background-attachment: fixed;
  color: #eef5ff;
}

main {
  width: min(900px, 92%);
  margin: 40px auto;
}

h1 {
  color: #7cc4ff;
  margin-bottom: 8px;
}

p {
  color: #b7c9dc;
}

.controls {
  display: flex;
  gap: 12px;
  align-items: end;
  flex-wrap: wrap;
  margin: 28px 0 20px;
}

label {
  display: flex;
  flex-direction: column;
  gap: 8px;
  color: #c9d9eb;
}

input {
  width: 160px;
  padding: 10px;
  border: 1px solid #52718e;
  border-radius: 6px;
  background: #122238;
  color: white;
  font-size: 16px;
}

button {
  padding: 11px 18px;
  border: 0;
  border-radius: 6px;
  background: #4ba3f2;
  color: #06111f;
  font-size: 16px;
  font-weight: bold;
  cursor: pointer;
}

button:hover {
  background: #7cc4ff;
}

#results {
  min-height: 90px;
  padding: 18px;
  margin-bottom: 20px;
  border-radius: 8px;
  background: #122238;
  color: #dcecff;
  line-height: 1.7;
}

.results-panel h2 {
  margin: 0 0 10px;
  color: #eef5ff;
  font-size: 20px;
}

.result-interpretation {
  display: inline-block;
  margin-top: 6px;
  color: #b7c9dc;
}

.result-caveat {
  margin: 8px 0 0;
  color: #9db1c6;
  font-size: 13px;
}

canvas {
  width: 100%;
  background: white;
  border-radius: 8px;
}

.top-bar {
  display: flex;
  justify-content: space-between;
  gap: 20px;
  align-items: start;
}

#language-button {
  white-space: nowrap;
}

input[type="range"] {
  width: 110px;
  padding: 0;
}

output {
  color: #7cc4ff;
  font-weight: bold;
}

.noise-inputs {
  display: flex;
  align-items: center;
  gap: 8px;
}

#noise-number {
  width: 70px;
}

.controls > label:not(.noise-control) input {
  width: 130px;
}

.simulation-action {
  display: flex;
  align-items: center;
  align-self: flex-end;
  gap: 10px;
  white-space: nowrap;
}

#simulation-status {
  color: #7cc4ff;
  font-weight: bold;
}

.observation-control {
  flex-basis: 100%;
  flex-direction: row;
  align-items: center;
  gap: 12px;
}

.observation-control input {
  width: 110px;
}

.model-note {
  margin: 0 0 22px;
  padding: 16px 18px;
  border: 1px solid #29445f;
  border-radius: 8px;
  background: #0e1b2c;
  color: #c9d9eb;
  line-height: 1.65;
}

.model-note summary {
  color: #7cc4ff;
  cursor: pointer;
  font-weight: bold;
}

.model-note p:last-child {
  margin-bottom: 0;
}

.model-note code {
  color: #eef5ff;
}

.chart-section h2 {
  margin: 0 0 12px;
  color: #eef5ff;
  font-size: 20px;
}

.visually-hidden {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}

.top-actions {
  display: flex;
  align-items: center;
  gap: 14px;
}

.back-home {
  color: #b7c9dc;
  text-decoration: none;
  white-space: nowrap;
}

.back-home:hover {
  color: #7cc4ff;
}

.home-page {
  background:
    linear-gradient(180deg, rgba(5, 11, 24, 0.38), rgba(5, 11, 24, 0.78)),
    url("images/hubble-extreme-deep-field.jpg") center 42% / cover fixed,
    #080f1d;
}

.transit-page {
  background-image:
    linear-gradient(180deg, rgba(5, 11, 24, 0.81), rgba(5, 11, 24, 0.9)),
    url("images/kepler-9-transit-concept.jpg");
  background-position: center 20%;
}

.image-credit {
  color: #a9bbcf;
  font-size: 12px;
  line-height: 1.5;
  text-decoration: none;
}

.image-credit:hover {
  color: #d8e9fa;
  text-decoration: underline;
}

.page-image-credit {
  padding: 22px 0 30px;
  text-align: right;
}

.home-footer p {
  margin: 0 0 8px;
}

.home-footer .image-credit {
  display: inline-block;
  max-width: 100%;
  text-align: center;
}

.solar-page {
  background:
    linear-gradient(180deg, rgba(5, 11, 24, 0.7), rgba(5, 11, 24, 0.83)),
    url("images/solar-system-eight-planets.jpg") center 28% / cover fixed,
    #080f1d;
  background-attachment: fixed;
}

.moon-page {
  background:
    linear-gradient(180deg, rgba(5, 11, 24, 0.72), rgba(5, 11, 24, 0.88)),
    url("images/solar-system-eight-planets.jpg") center 28% / cover fixed,
    #080f1d;
}

.moon-main {
  width: min(900px, 92%);
  margin: 34px auto 0;
}

.moon-intro {
  max-width: 720px;
  margin: 34px 0 24px;
  color: #c1d2e3;
  line-height: 1.7;
}

.moon-intro h2 {
  margin: 0;
  color: #eef5ff;
  font-size: clamp(25px, 4vw, 34px);
}

.moon-intro > p:last-child {
  margin-bottom: 0;
}

.moon-day-badge {
  flex: 0 0 auto;
  padding: 8px 12px;
  border: 1px solid rgba(137, 176, 211, 0.24);
  border-radius: 999px;
  color: #b7c9dc;
  font-size: 13px;
}

.moon-day-badge strong {
  color: #eef5ff;
  font-variant-numeric: tabular-nums;
}

.moon-visual {
  margin: 18px auto 10px;
  overflow: hidden;
  border: 1px solid rgba(119, 157, 193, 0.14);
  border-radius: 14px;
  background: radial-gradient(ellipse at center, rgba(29, 56, 84, 0.58), rgba(6, 14, 26, 0.88) 72%);
}

.moon-orbit-svg {
  display: block;
  width: 100%;
  height: auto;
}

.moon-orbit-svg text {
  fill: #c9d9eb;
  font-family: Arial, sans-serif;
  font-size: 13px;
}

.sun-direction path {
  fill: none;
  stroke: #f2b158;
  stroke-width: 2;
}

.moon-orbit-track {
  fill: none;
  stroke: rgba(164, 191, 216, 0.42);
  stroke-dasharray: 4 7;
  stroke-width: 1.5;
}

.earth-body {
  stroke: rgba(171, 222, 255, 0.8);
  stroke-width: 1.5;
}

.earth-label {
  font-weight: bold;
}

.orbiting-moon circle:first-child {
  stroke: rgba(255, 255, 255, 0.65);
  stroke-width: 1;
}

.tidal-bulge ellipse {
  fill: rgba(74, 162, 218, 0.2);
  stroke: rgba(124, 196, 255, 0.86);
  stroke-width: 1.5;
  stroke-dasharray: 4 3;
  transition: rx 120ms ease, transform 120ms ease;
}

.tidal-bulge circle {
  fill: #a8dfff;
  filter: drop-shadow(0 0 4px rgba(124, 196, 255, 0.9));
}

.orbit-moon-shadow,
.moon-disc-shadow {
  fill: #111824;
}

.moon-orbit-label {
  fill: #91a9c1 !important;
  font-size: 11px !important;
}

.moon-phase-summary {
  display: flex;
  align-items: center;
  gap: 18px;
  width: fit-content;
  margin: 22px auto;
}

.moon-phase-disc {
  width: 92px;
  height: 92px;
  flex: 0 0 auto;
  filter: drop-shadow(0 0 18px rgba(236, 231, 208, 0.15));
}

.moon-phase-disc svg {
  display: block;
  width: 100%;
  height: 100%;
}

.moon-disc-lit {
  fill: #e9e5d8;
}

.moon-phase-summary .eyebrow {
  margin-bottom: 5px;
}

.moon-phase-summary h3 {
  margin: 0;
  color: #f0f6fc;
  font-size: 21px;
}

.phase-illumination-text {
  margin: 6px 0 0;
  color: #a9bbcf;
  font-size: 14px;
}

.phase-illumination-text strong {
  color: #f0f6fc;
  font-variant-numeric: tabular-nums;
}

.moon-time-control {
  display: flex;
  flex-direction: column;
  gap: 10px;
  margin-top: 24px;
  color: #c9d9eb;
  font-weight: bold;
}

.moon-time-control input[type="range"] {
  width: 100%;
  accent-color: #7cc4ff;
}

.moon-range-labels {
  display: flex;
  justify-content: space-between;
  gap: 8px;
  color: #9fb4c9;
  font-size: 11px;
  font-weight: normal;
}

.moon-facts-grid {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 10px;
  margin: 18px 0 0;
}

.moon-facts-grid > div {
  min-width: 0;
  padding: 13px;
  border: 1px solid rgba(137, 176, 211, 0.14);
  border-radius: 10px;
  background: rgba(5, 13, 25, 0.42);
}

.moon-facts-grid dt {
  margin-bottom: 7px;
  color: #91a9c1;
  font-size: 12px;
  line-height: 1.5;
}

.moon-facts-grid dd {
  margin: 0;
  color: #f0f6fc;
  font-size: 15px;
  font-weight: bold;
  line-height: 1.45;
}

.moon-explanation {
  margin: 16px 0 0;
  color: #c1d2e3;
  font-size: 14px;
  line-height: 1.7;
}

.binary-page {
  background-image:
    radial-gradient(ellipse at 50% 18%, rgba(32, 60, 93, 0.42), transparent 55%),
    linear-gradient(180deg, rgba(5, 11, 24, 0.84), rgba(5, 11, 24, 0.94)),
    url("images/hubble-extreme-deep-field.jpg");
  background-position: center top;
}

.binary-main {
  width: min(1080px, 92%);
  margin: 36px auto;
}

.binary-intro {
  max-width: 820px;
  margin: 34px 0 24px;
  line-height: 1.7;
}

.binary-intro h2,
.binary-explanation h2 {
  margin: 0;
  color: #eef5ff;
  font-size: clamp(24px, 4vw, 34px);
}

.binary-intro > p:last-child,
.binary-explanation > p:not(.eyebrow) {
  color: #b7c9dc;
  line-height: 1.75;
}

.binary-panel,
.binary-explanation {
  margin-top: 18px;
  padding: 26px;
  border: 1px solid rgba(124, 196, 255, 0.2);
  border-radius: 14px;
  background: linear-gradient(145deg, rgba(18, 34, 56, 0.88), rgba(9, 20, 35, 0.9));
}

.binary-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}

.binary-actions .secondary-button {
  white-space: nowrap;
}

.binary-controls {
  display: grid;
  grid-template-columns: minmax(160px, 1fr) minmax(220px, 1.4fr) minmax(180px, 1fr);
  gap: 14px;
  margin: 22px 0 16px;
}

.binary-control {
  min-width: 0;
  gap: 8px;
  color: #c9d9eb;
  font-size: 13px;
}

.binary-control select {
  width: 100%;
  min-height: 42px;
  padding: 9px 30px 9px 11px;
  border: 1px solid #52718e;
  border-radius: 7px;
  background: #122238;
  color: #eef5ff;
  font: inherit;
}

.binary-speed-control input[type="range"] {
  width: 100%;
  accent-color: #7cc4ff;
}

.binary-speed-control output {
  margin-left: 5px;
  font-variant-numeric: tabular-nums;
}

.binary-visual {
  overflow: hidden;
  border: 1px solid rgba(119, 157, 193, 0.18);
  border-radius: 12px;
  background: radial-gradient(ellipse at center, rgba(32, 62, 92, 0.45), rgba(4, 11, 21, 0.92) 75%);
}

.binary-visual canvas {
  display: block;
  width: 100%;
  height: auto;
  aspect-ratio: 5 / 3;
  background: transparent;
  border-radius: 0;
}

.star-legend {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
  margin-top: 14px;
}

.star-legend-item {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  padding: 7px 10px;
  border: 1px solid rgba(137, 176, 211, 0.16);
  border-radius: 999px;
  color: #c9d9eb;
  font-size: 12px;
}

.star-legend-item i {
  width: 9px;
  height: 9px;
  border-radius: 50%;
  background: var(--star-color);
  box-shadow: 0 0 9px var(--star-color);
}

.star-legend-item strong {
  color: #eef5ff;
  font-variant-numeric: tabular-nums;
}

.binary-stats {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 10px;
  margin: 16px 0 0;
}

.binary-stats > div {
  padding: 12px 14px;
  border: 1px solid rgba(137, 176, 211, 0.14);
  border-radius: 10px;
  background: rgba(5, 13, 25, 0.38);
}

.binary-stats dt {
  color: #91a9c1;
  font-size: 12px;
}

.binary-stats dd {
  margin: 6px 0 0;
  color: #eef5ff;
  font-size: 15px;
  font-weight: bold;
  font-variant-numeric: tabular-nums;
}

.binary-explanation .model-note {
  margin-top: 18px;
}

.binary-main .solar-footer {
  padding-bottom: 32px;
}

.binary-page button:focus-visible,
.binary-page select:focus-visible,
.binary-page input:focus-visible {
  outline: 2px solid #a4d7ff;
  outline-offset: 3px;
}

.tide-status {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 24px;
  margin-top: 20px;
  padding: 16px;
  border: 1px solid rgba(137, 176, 211, 0.16);
  border-radius: 12px;
  background: rgba(5, 13, 25, 0.38);
}

.tide-state-label {
  margin: 0 0 5px;
  color: #9fb4c9;
  font-size: 12px;
}

.tide-status h3 {
  margin: 0;
  color: #f0f6fc;
  font-size: 19px;
}

.tide-strength {
  width: min(320px, 52%);
}

.tide-strength-heading {
  display: flex;
  justify-content: space-between;
  gap: 12px;
  margin-bottom: 8px;
  color: #a9bbcf;
  font-size: 12px;
}

.tide-strength-heading strong {
  color: #f0f6fc;
  font-variant-numeric: tabular-nums;
}

.tide-strength-track {
  height: 9px;
  overflow: hidden;
  border-radius: 999px;
  background: rgba(137, 176, 211, 0.16);
}

.tide-strength-track span {
  display: block;
  width: 100%;
  height: 100%;
  border-radius: inherit;
  background: linear-gradient(90deg, #4ba3f2, #83d8dc);
  transition: width 140ms ease;
}

.tide-types {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 12px;
  margin-top: 18px;
}

.tide-types article {
  padding: 14px;
  border: 1px solid rgba(137, 176, 211, 0.14);
  border-radius: 10px;
  background: rgba(5, 13, 25, 0.32);
}

.tide-types h3 {
  margin: 0 0 7px;
  color: #dcecff;
  font-size: 15px;
}

.tide-types p {
  margin: 0;
  color: #b7c9dc;
  font-size: 13px;
  line-height: 1.6;
}

.tide-model-note {
  margin: 18px 0 0;
}

.solar-main {
  width: min(1000px, 92%);
  margin: 34px auto 0;
}

.solar-intro {
  max-width: 720px;
  margin: 34px 0 24px;
  color: #c1d2e3;
  font-size: 17px;
  line-height: 1.7;
}

.solar-intro p:last-child {
  margin-bottom: 0;
}

.solar-panel {
  margin: 18px 0;
  padding: 24px;
  border: 1px solid rgba(137, 176, 211, 0.2);
  border-radius: 16px;
  background: linear-gradient(145deg, rgba(14, 28, 47, 0.94), rgba(9, 19, 34, 0.94));
  box-shadow: 0 18px 55px rgba(0, 0, 0, 0.16);
}

.solar-section-heading {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 18px;
}

.solar-section-heading .eyebrow,
.solar-panel > .eyebrow {
  margin-bottom: 7px;
}

.solar-panel h2 {
  margin: 0;
  color: #eef5ff;
  font-size: clamp(21px, 3vw, 27px);
}

.section-description {
  max-width: 760px;
  margin: 12px 0 0;
  color: #9fb4c9;
  font-size: 14px;
  line-height: 1.65;
}

.secondary-button {
  flex: 0 0 auto;
  border: 1px solid #526d89;
  background: rgba(18, 34, 56, 0.82);
  color: #e2effc;
}

.secondary-button:hover {
  background: #1b3551;
}

.orbit-visual {
  overflow: hidden;
  margin: 18px auto 8px;
  border: 1px solid rgba(119, 157, 193, 0.14);
  border-radius: 14px;
  background:
    radial-gradient(ellipse at center, rgba(29, 56, 84, 0.58), rgba(6, 14, 26, 0.88) 72%);
}

.orbit-svg {
  display: block;
  width: 100%;
  height: auto;
  max-height: 620px;
}

.orbit-tracks circle {
  fill: none;
  stroke: rgba(164, 191, 216, 0.24);
  stroke-width: 1.25;
  stroke-dasharray: 3 6;
}

.sun-glow {
  fill: url(#sun-glow);
}

.sun-core {
  fill: #fff4c2;
  filter: drop-shadow(0 0 9px rgba(255, 196, 94, 0.9));
}

.sun-hit-area {
  fill: transparent;
  cursor: pointer;
}

.sun-select:focus-visible {
  outline: none;
}

.sun-select:focus-visible .sun-core {
  stroke: #ffffff;
  stroke-width: 3;
}

.orbit-motion {
  transform-box: view-box;
  transform-origin: 400px 325px;
  animation: orbit-revolution var(--orbit-duration) linear infinite;
}

.orbit-motion circle {
  stroke: rgba(255, 255, 255, 0.6);
  stroke-width: 1;
  transition: filter 180ms ease, stroke-width 180ms ease;
}

.orbit-motion.mercury-orbit circle { fill: #aaa39b; }
.orbit-motion.venus-orbit circle { fill: #e6b875; }
.orbit-motion.earth-orbit circle { fill: #61a9f2; }
.orbit-motion.mars-orbit circle { fill: #e37b58; }
.orbit-motion.jupiter-orbit circle { fill: #dfa779; }
.orbit-motion.saturn-orbit circle { fill: #e8cd87; }
.orbit-motion.uranus-orbit circle { fill: #81d5dc; }
.orbit-motion.neptune-orbit circle { fill: #5d84ee; }

.saturn-rings {
  fill: none;
  stroke: #eed89f;
  stroke-width: 2.5;
}

.orbit-visual.is-paused .orbit-motion {
  animation-play-state: paused;
}

.orbit-visual[data-selected="mercury"] .mercury-orbit circle,
.orbit-visual[data-selected="venus"] .venus-orbit circle,
.orbit-visual[data-selected="earth"] .earth-orbit circle,
.orbit-visual[data-selected="mars"] .mars-orbit circle,
.orbit-visual[data-selected="jupiter"] .jupiter-orbit circle,
.orbit-visual[data-selected="saturn"] .saturn-orbit circle,
.orbit-visual[data-selected="uranus"] .uranus-orbit circle,
.orbit-visual[data-selected="neptune"] .neptune-orbit circle {
  filter: drop-shadow(0 0 8px currentColor);
  stroke: #ffffff;
  stroke-width: 2;
}

.orbit-visual[data-selected="sun"] .sun-core {
  stroke: #ffffff;
  stroke-width: 2;
  filter: drop-shadow(0 0 14px rgba(255, 208, 105, 1));
}

@keyframes orbit-revolution {
  from { transform: rotate(0deg); }
  to { transform: rotate(360deg); }
}

.planet-picker {
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  gap: 8px;
  margin-top: 16px;
}

.planet-choice {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 8px 12px;
  border: 1px solid rgba(137, 176, 211, 0.24);
  border-radius: 999px;
  background: rgba(8, 17, 31, 0.64);
  color: #c9d9eb;
  font-size: 14px;
  font-weight: normal;
}

.planet-choice:hover,
.planet-choice.is-selected {
  border-color: #7cc4ff;
  background: rgba(46, 93, 137, 0.4);
  color: #fff;
}

.planet-choice:focus-visible,
.size-planet:focus-visible,
.secondary-button:focus-visible {
  outline: 2px solid #a4d7ff;
  outline-offset: 3px;
}

.planet-swatch {
  width: 10px;
  height: 10px;
  flex: 0 0 auto;
  border-radius: 50%;
}

.sun-swatch { background: #ffc45e; box-shadow: 0 0 8px rgba(255, 196, 94, 0.8); }
.mercury-swatch { background: #aaa39b; }
.venus-swatch { background: #e6b875; }
.earth-swatch { background: #61a9f2; }
.mars-swatch { background: #e37b58; }
.jupiter-swatch { background: #dfa779; }
.saturn-swatch { background: #e8cd87; }
.uranus-swatch { background: #81d5dc; }
.neptune-swatch { background: #5d84ee; }

.planet-detail-panel {
  border-color: rgba(124, 196, 255, 0.3);
}

.detail-heading {
  align-items: flex-end;
}

.planet-type {
  padding: 6px 11px;
  border: 1px solid rgba(124, 196, 255, 0.24);
  border-radius: 999px;
  color: #9ecbf0;
  font-size: 13px;
}

.planet-fact {
  max-width: 800px;
  margin: 15px 0 20px;
  color: #c4d6e8;
  line-height: 1.7;
}

.planet-stats {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 10px;
  margin: 0;
}

.planet-stats > div {
  min-width: 0;
  padding: 13px;
  border: 1px solid rgba(137, 176, 211, 0.14);
  border-radius: 10px;
  background: rgba(5, 13, 25, 0.42);
}

.planet-stats dt {
  margin-bottom: 7px;
  color: #91a9c1;
  font-size: 12px;
  line-height: 1.5;
}

.planet-stats dd {
  margin: 0;
  color: #f0f6fc;
  font-size: 15px;
  font-weight: bold;
  line-height: 1.45;
  overflow-wrap: anywhere;
}

.unit-note {
  margin: 12px 0 0;
  color: #8fa7bf;
  font-size: 12px;
  line-height: 1.6;
}

.kepler-result {
  margin: 16px 0 0;
  padding: 12px 14px;
  border-left: 3px solid #f2b158;
  background: rgba(242, 177, 88, 0.08);
  color: #d7e3ef;
  font-size: 13px;
  line-height: 1.7;
}

.kepler-result strong {
  color: #f5c879;
}

.kepler-result-note {
  border-left-color: #ffc45e;
}

.size-comparison {
  display: grid;
  grid-template-columns: repeat(8, minmax(0, 1fr));
  gap: 8px;
  align-items: stretch;
  margin-top: 20px;
}

.size-planet {
  display: flex;
  min-width: 0;
  flex-direction: column;
  align-items: center;
  justify-content: flex-end;
  gap: 6px;
  padding: 12px 5px;
  border: 1px solid transparent;
  border-radius: 10px;
  background: rgba(5, 13, 25, 0.32);
  color: #c9d9eb;
  font-size: 12px;
  font-weight: normal;
}

.size-planet:hover,
.size-planet.is-selected {
  border-color: rgba(124, 196, 255, 0.52);
  background: rgba(46, 93, 137, 0.28);
}

.size-orb {
  display: block;
  width: var(--planet-size);
  height: var(--planet-size);
  flex: 0 0 auto;
  border: 1px solid rgba(255, 255, 255, 0.42);
  border-radius: 50%;
  box-shadow: inset -5px -4px 9px rgba(0, 0, 0, 0.28), 0 0 12px rgba(108, 166, 220, 0.14);
}

.size-planet-name {
  margin-top: 8px;
  color: #eef5ff;
  font-weight: bold;
}

.size-planet-value,
.size-earth-ratio {
  color: #a9bbcf;
  font-size: 10px;
  text-align: center;
}

.planet-comparison {
  margin-top: 28px;
  padding-top: 22px;
  border-top: 1px solid rgba(137, 176, 211, 0.18);
}

.planet-comparison h3 {
  margin: 0;
  color: #eef5ff;
  font-size: 18px;
}

.comparison-picker {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin-top: 14px;
}

.comparison-planet {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 8px 12px;
  border: 1px solid rgba(137, 176, 211, 0.24);
  border-radius: 999px;
  background: rgba(8, 17, 31, 0.64);
  color: #c9d9eb;
  font-size: 14px;
  font-weight: normal;
}

.comparison-planet:hover,
.comparison-planet.is-selected {
  border-color: #7cc4ff;
  background: rgba(46, 93, 137, 0.4);
  color: #fff;
}

.comparison-planet:focus-visible {
  outline: 2px solid #a4d7ff;
  outline-offset: 3px;
}

.comparison-results {
  margin-top: 16px;
}

.comparison-empty {
  margin: 0;
  color: #a9bbcf;
  font-size: 13px;
}

.comparison-table-wrap {
  overflow-x: auto;
  border: 1px solid rgba(137, 176, 211, 0.18);
  border-radius: 10px;
}

.comparison-table {
  width: 100%;
  min-width: 480px;
  border-collapse: collapse;
  text-align: left;
}

.comparison-table th,
.comparison-table td {
  padding: 11px 13px;
  border-bottom: 1px solid rgba(137, 176, 211, 0.14);
  color: #dce9f6;
  font-size: 13px;
  line-height: 1.5;
  vertical-align: top;
}

.comparison-table thead th {
  background: rgba(46, 93, 137, 0.2);
  color: #f0f6fc;
}

.comparison-table tbody th {
  width: 26%;
  color: #91a9c1;
  font-weight: normal;
}

.comparison-table tbody tr:last-child th,
.comparison-table tbody tr:last-child td {
  border-bottom: 0;
}

.comparison-planet-heading {
  display: inline-flex;
  align-items: center;
  gap: 8px;
}

.kepler-panel > p:not(.eyebrow) {
  color: #c1d2e3;
  line-height: 1.75;
}

.kepler-panel .book-reference {
  margin-bottom: 0;
  color: #91a9c1;
  font-size: 13px;
}

.solar-footer {
  display: flex;
  flex-wrap: wrap;
  justify-content: space-between;
  gap: 8px 20px;
  padding: 18px 0 32px;
}

@media (prefers-reduced-motion: reduce) {
  .orbit-visual:not(.motion-enabled) .orbit-motion {
    animation: none;
  }
}

@media (max-width: 640px) {
  .binary-page {
    background-attachment: scroll;
  }

  .binary-main {
    width: min(100% - 28px, 520px);
    margin-top: 22px;
  }

  .binary-panel,
  .binary-explanation {
    padding: 18px 14px;
  }

  .binary-controls {
    grid-template-columns: 1fr;
    gap: 12px;
  }

  .binary-stats {
    grid-template-columns: 1fr;
  }

  .binary-visual canvas {
    min-height: 240px;
  }

  .solar-page {
    background-attachment: scroll;
  }

  .moon-page {
    background-attachment: scroll;
  }

  .solar-main {
    width: min(100% - 28px, 520px);
    margin-top: 22px;
  }

  .moon-main {
    width: min(100% - 28px, 520px);
    margin-top: 22px;
  }

  .moon-intro {
    margin-top: 24px;
    font-size: 15px;
  }

  .solar-intro {
    margin-top: 24px;
    font-size: 15px;
  }

  .solar-panel {
    padding: 18px 14px;
  }

  .moon-day-badge {
    align-self: flex-start;
  }

  .moon-facts-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .moon-range-labels {
    font-size: 10px;
  }

  .tide-status {
    align-items: stretch;
    flex-direction: column;
    gap: 14px;
  }

  .tide-strength {
    width: 100%;
  }

  .tide-types {
    grid-template-columns: 1fr;
  }

  .solar-section-heading {
    align-items: flex-start;
    flex-direction: column;
  }

  .orbit-svg {
    width: 100%;
    max-width: 100%;
  }

  .orbit-visual {
    height: auto;
  }

  .planet-stats {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .size-comparison {
    grid-template-columns: repeat(4, minmax(0, 1fr));
  }

  .solar-footer {
    flex-direction: column;
  }
}

.frontier-game-heading,
.frontier-log-heading {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
}

.frontier-game-heading h2 {
  margin: 0;
  color: #eef5ff;
  font-size: clamp(22px, 3vw, 29px);
}

.frontier-stats {
  display: grid;
  grid-template-columns: repeat(5, minmax(0, 1fr));
  gap: 10px;
  margin: 24px 0;
}

.frontier-stat {
  display: flex;
  min-height: 75px;
  flex-direction: column;
  justify-content: space-between;
  gap: 8px;
  padding: 13px;
  border: 1px solid rgba(137, 176, 211, 0.18);
  border-radius: 10px;
  background: rgba(7, 17, 31, 0.68);
  color: #9fb4c9;
  font-size: 12px;
}

.frontier-stat strong {
  color: #eef5ff;
  font-size: 20px;
}

.frontier-meter-group {
  display: grid;
  grid-template-columns: 1fr auto;
  gap: 8px 12px;
  align-items: center;
  margin-bottom: 22px;
}

.frontier-meter-heading {
  display: contents;
  color: #b7c9dc;
  font-size: 13px;
}

.frontier-meter-heading strong {
  color: #eef5ff;
}

.frontier-meter {
  overflow: hidden;
  height: 9px;
  grid-column: 1 / -1;
  border-radius: 99px;
  background: #091321;
}

.frontier-meter span {
  display: block;
  width: 12%;
  height: 100%;
  border-radius: inherit;
  background: linear-gradient(90deg, #55bd9a, #f0b452, #eb6b62);
  transition: width 180ms ease;
}

.frontier-pressure span {
  background: linear-gradient(90deg, #7cc4ff, #b078e6, #eb6b62);
}

.frontier-map-panel,
.frontier-log-panel {
  padding: 16px;
  border: 1px solid rgba(137, 176, 211, 0.16);
  border-radius: 12px;
  background: rgba(7, 17, 31, 0.55);
}

.frontier-map-heading {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
}

.frontier-map-heading h3 {
  margin: 0;
  color: #eef5ff;
  font-size: 16px;
}

.frontier-map-heading > span {
  color: #9fb4c9;
  font-size: 12px;
}

.frontier-map-heading strong {
  color: #7cc4ff;
}

.frontier-map-viewport {
  overflow: hidden;
  margin-top: 13px;
  border: 1px solid rgba(124, 196, 255, 0.16);
  border-radius: 12px;
  background: #07111f;
}

.frontier-starmap {
  display: block;
  width: 100%;
  height: auto;
  min-height: 230px;
}

.starmap-background {
  fill: #07111f;
}

.starmap-stars circle {
  fill: #cde6ff;
  opacity: 0.65;
  animation: star-twinkle 3.8s ease-in-out infinite;
}

.starmap-stars circle:nth-child(3n) {
  animation-delay: -1.5s;
}

.starmap-stars circle:nth-child(2n) {
  animation-delay: -2.4s;
}

.starmap-routes path {
  fill: none;
  stroke: rgba(124, 196, 255, 0.34);
  stroke-dasharray: 4 8;
  stroke-width: 1.5;
}

.starmap-routes .swarm-route {
  stroke: rgba(235, 107, 98, 0.62);
  stroke-dasharray: 3 7;
  animation: route-drift 7s linear infinite;
}

.frontier-world-node {
  cursor: pointer;
  outline: none;
}

.world-target-ring {
  fill: rgba(124, 196, 255, 0.02);
  stroke: transparent;
  stroke-width: 2;
  transition: fill 150ms ease, stroke 150ms ease;
}

.world-orbit {
  fill: none;
  stroke: rgba(160, 192, 220, 0.44);
  stroke-dasharray: 3 5;
  stroke-width: 1;
  animation: orbit-drift 14s linear infinite;
}

.world-body {
  stroke: rgba(225, 240, 255, 0.8);
  stroke-width: 1.5;
}

.world-ice {
  fill: #b9d6e8;
}

.world-rock {
  fill: #bb8464;
}

.world-ocean {
  fill: #337faa;
}

.world-desert {
  fill: #d5a958;
}

.world-detail {
  fill: none;
  stroke: rgba(8, 18, 32, 0.6);
  stroke-linecap: round;
  stroke-width: 2;
}

.colony-marker {
  display: none;
  fill: #82d9b1;
  stroke: #07111f;
  stroke-width: 1.5;
}

.frontier-world-node.is-colonized .colony-marker {
  display: block;
}

.world-map-name,
.world-map-status {
  fill: #dcecff;
  font-family: Arial, sans-serif;
  font-size: 10px;
  font-weight: bold;
  letter-spacing: 0.07em;
  pointer-events: none;
  text-anchor: middle;
}

.world-map-status {
  fill: #8fa7bf;
  font-size: 8px;
  font-weight: normal;
  letter-spacing: 0.02em;
}

.frontier-world-node.is-undiscovered .world-body {
  filter: grayscale(0.7);
  opacity: 0.64;
}

.frontier-world-node.is-selected .world-target-ring,
.frontier-world-node:hover .world-target-ring,
.frontier-world-node:focus-visible .world-target-ring {
  fill: rgba(124, 196, 255, 0.12);
  stroke: #7cc4ff;
}

.frontier-world-node.is-colonized .world-target-ring {
  stroke: #82d9b1;
}

.map-sun {
  fill: #ffe7a3;
  filter: drop-shadow(0 0 8px rgba(242, 177, 88, 0.9));
  transform-box: fill-box;
  transform-origin: center;
  animation: sun-pulse 3s ease-in-out infinite;
}

.fleet-engine-glow {
  fill: rgba(124, 196, 255, 0.22);
  transform-box: fill-box;
  transform-origin: center;
  animation: engine-pulse 450ms ease-in-out infinite alternate;
}

.map-fleet-ship,
.map-fleet-tail {
  pointer-events: none;
}

.map-fleet-ship {
  fill: #7cc4ff;
  filter: drop-shadow(0 0 5px rgba(124, 196, 255, 0.9));
}

.map-fleet-tail {
  fill: none;
  stroke: #b7e4ff;
  stroke-linecap: round;
  stroke-width: 2;
}

.starmap-home text,
.starmap-swarm text {
  fill: #b7c9dc;
  font-family: Arial, sans-serif;
  font-size: 9px;
  font-weight: bold;
  letter-spacing: 0.12em;
  text-anchor: middle;
}

.swarm-pulse {
  fill: rgba(235, 107, 98, 0.06);
  stroke: rgba(235, 107, 98, 0.34);
  stroke-width: 1;
  animation: swarm-pulse 2.8s ease-in-out infinite;
}

.swarm-core {
  fill: #d96f71;
  filter: drop-shadow(0 0 8px rgba(235, 107, 98, 0.55));
  transform-box: fill-box;
  transform-origin: center;
  animation: swarm-turn 18s linear infinite;
}

.starmap-swarm {
  transition: transform 700ms cubic-bezier(0.2, 0.8, 0.25, 1);
}

.starmap-swarm.is-attacking .swarm-core {
  fill: #ff9a84;
  filter: drop-shadow(0 0 16px rgba(255, 104, 92, 0.95));
}

.target-route {
  stroke: rgba(124, 196, 255, 0.92) !important;
  stroke-dasharray: 2 7 !important;
  animation: route-drift 900ms linear infinite !important;
}

.swarm-eye {
  fill: #ffe1b4;
}

.frontier-map-hint {
  margin: 10px 0 0;
  color: #8fa7bf;
  font-size: 12px;
  line-height: 1.5;
}

.frontier-command-dock {
  margin-top: 15px;
  overflow: hidden;
  border: 1px solid rgba(124, 196, 255, 0.24);
  border-radius: 11px;
  background: linear-gradient(145deg, rgba(15, 31, 51, 0.96), rgba(8, 19, 33, 0.97));
}

.frontier-command-heading {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 11px 13px;
  border-bottom: 1px solid rgba(137, 176, 211, 0.14);
  color: #9fb4c9;
  font-size: 12px;
  letter-spacing: 0.06em;
  text-transform: uppercase;
}

.frontier-command-heading strong {
  color: #7cc4ff;
  letter-spacing: 0;
  text-transform: none;
}

.frontier-command-grid {
  display: grid;
  grid-template-columns: repeat(5, minmax(0, 1fr));
  gap: 1px;
  background: rgba(137, 176, 211, 0.13);
}

.frontier-command-utility {
  display: flex;
  justify-content: flex-end;
  gap: 8px;
  padding: 8px 10px;
  border-top: 1px solid rgba(137, 176, 211, 0.14);
  background: rgba(7, 17, 31, 0.92);
}

button.frontier-reset-command {
  display: inline-flex;
  min-height: 34px;
  align-items: center;
  justify-content: center;
  gap: 7px;
  padding: 7px 11px;
  border: 1px solid rgba(124, 196, 255, 0.24);
  border-radius: 7px;
  background: rgba(18, 34, 56, 0.92);
  color: #b7c9dc;
  font-size: 12px;
}

button.frontier-reset-command:hover {
  border-color: #7cc4ff;
  background: #17314e;
  color: #eef5ff;
}

button.frontier-language-command {
  min-width: 74px;
  color: #7cc4ff;
}

button.frontier-command {
  display: flex;
  min-width: 0;
  min-height: 86px;
  align-items: flex-start;
  gap: 9px;
  padding: 13px 10px;
  border: 0;
  border-radius: 0;
  background: rgba(8, 19, 33, 0.98);
  color: #eef5ff;
  text-align: left;
  transition: background-color 150ms ease, color 150ms ease;
}

button.frontier-command:hover:not(:disabled),
button.frontier-command:focus-visible:not(:disabled) {
  background: #17314e;
  outline: 1px solid #7cc4ff;
  outline-offset: -2px;
}

button.frontier-command:disabled {
  background: rgba(8, 19, 33, 0.78);
  color: #8295a9;
  cursor: not-allowed;
  opacity: 0.6;
}

.command-icon {
  display: grid;
  width: 27px;
  height: 27px;
  flex: 0 0 27px;
  place-items: center;
  border: 1px solid rgba(124, 196, 255, 0.3);
  border-radius: 7px;
  color: #7cc4ff;
  font-size: 17px;
}

.command-copy {
  display: grid;
  min-width: 0;
  gap: 6px;
}

.command-copy strong {
  font-size: 12px;
  line-height: 1.3;
}

.command-copy small {
  color: #91a8be;
  font-size: 10px;
  font-weight: normal;
  line-height: 1.4;
}

@keyframes swarm-pulse {
  0%, 100% { opacity: 0.38; }
  50% { opacity: 1; }
}

@keyframes route-drift {
  to { stroke-dashoffset: -40; }
}

@keyframes star-twinkle {
  0%, 100% { opacity: 0.3; }
  50% { opacity: 0.95; }
}

@keyframes orbit-drift {
  to { stroke-dashoffset: -32; }
}

@keyframes sun-pulse {
  0%, 100% { opacity: 0.82; }
  50% { opacity: 1; }
}

@keyframes engine-pulse {
  to { opacity: 0.4; transform: scale(1.2); }
}

@keyframes swarm-turn {
  to { transform: rotate(360deg); }
}

.frontier-log-heading h3 {
  margin: 0;
  color: #eef5ff;
  font-size: 16px;
}

.frontier-world-list,
.frontier-log {
  display: grid;
  gap: 8px;
  padding: 0;
  margin: 13px 0 0;
  list-style: none;
}

.frontier-world-list li {
  padding: 0;
}

.frontier-world-select {
  display: flex;
  width: 100%;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 10px 11px;
  border: 1px solid transparent;
  background: rgba(124, 196, 255, 0.07);
  color: #9fb4c9;
  font-size: 13px;
  text-align: left;
}

.frontier-world-select strong {
  color: #dcecff;
}

.frontier-world-list .is-undiscovered .frontier-world-select {
  opacity: 0.62;
}

.frontier-world-select[aria-pressed="true"],
.frontier-world-list .is-colonized .frontier-world-select {
  border-color: rgba(124, 196, 255, 0.48);
  background: rgba(124, 196, 255, 0.12);
}

.frontier-world-list .is-colonized .frontier-world-select {
  border-color: rgba(93, 190, 145, 0.35);
  background: rgba(93, 190, 145, 0.13);
}

.frontier-log-heading span {
  color: #82d9b1;
  font-size: 12px;
}

.frontier-log {
  max-height: 235px;
  overflow-y: auto;
}

.frontier-log li {
  padding: 8px 10px;
  border-left: 2px solid #4ba3f2;
  background: rgba(124, 196, 255, 0.06);
  color: #b7c9dc;
  font-size: 13px;
  line-height: 1.5;
}

.frontier-outcome {
  padding: 16px;
  margin: 16px 0 0;
  border: 1px solid rgba(235, 107, 98, 0.4);
  border-radius: 10px;
  background: rgba(235, 107, 98, 0.1);
  color: #ffc1b7;
  font-weight: bold;
}

.frontier-outcome.is-victory {
  border-color: rgba(93, 190, 145, 0.45);
  background: rgba(93, 190, 145, 0.1);
  color: #a7ebc8;
}

@media (max-width: 640px) {
  .frontier-game-heading,
  .frontier-log-heading {
    align-items: flex-start;
    flex-direction: column;
  }

  .frontier-stats {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .frontier-world-list li {
    min-width: 0;
  }

  .frontier-map-heading {
    align-items: flex-start;
    flex-direction: column;
  }

  .frontier-starmap {
    min-height: 170px;
  }

  .frontier-command-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  button.frontier-command {
    min-height: 76px;
  }
}

@media (max-width: 640px) {
  body {
    background-attachment: scroll;
  }

  .home-page {
    background-attachment: scroll;
  }

  .transit-page {
    background-attachment: scroll;
  }

  .page-image-credit {
    text-align: left;
  }
}

.home-page main {
  width: min(1080px, 90%);
  margin: 0 auto;
}

.home-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 28px 0;
  border-bottom: 1px solid rgba(183, 201, 220, 0.14);
}

.home-brand {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  color: #eef5ff;
  font-size: 17px;
  font-weight: bold;
  text-decoration: none;
}

.brand-symbol {
  color: #7cc4ff;
  font-size: 25px;
}

.home-header button {
  padding: 9px 14px;
  border: 1px solid #52718e;
  background: #122238;
  color: #eef5ff;
}

.home-header button:hover {
  background: #1a3452;
}

.home-hero {
  max-width: 760px;
  padding: 76px 0 64px;
}

.eyebrow {
  margin: 0 0 14px;
  color: #7cc4ff;
  font-size: 12px;
  font-weight: bold;
  letter-spacing: 0.13em;
  text-transform: uppercase;
}

.home-hero h1 {
  max-width: 700px;
  margin: 0;
  color: #eef5ff;
  font-size: clamp(38px, 7vw, 66px);
  letter-spacing: -0.045em;
  line-height: 1.08;
}

.home-intro {
  max-width: 600px;
  margin: 22px 0 0;
  font-size: 18px;
  line-height: 1.7;
}

.module-section {
  padding-bottom: 70px;
}

.section-heading {
  display: flex;
  align-items: end;
  justify-content: space-between;
  gap: 20px;
  margin-bottom: 20px;
}

.section-heading .eyebrow {
  margin-bottom: 8px;
}

.section-heading h2 {
  margin: 0;
  color: #eef5ff;
  font-size: 26px;
}

.module-count {
  padding-bottom: 4px;
  color: #8fa7bf;
  font-size: 13px;
}

.module-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(min(100%, 280px), 1fr));
  gap: 18px;
}

.module-card {
  display: flex;
  min-height: 300px;
  flex-direction: column;
  align-items: flex-start;
  padding: 26px;
  border: 1px solid rgba(124, 196, 255, 0.2);
  border-radius: 14px;
  background: linear-gradient(145deg, rgba(18, 34, 56, 0.96), rgba(13, 25, 42, 0.96));
  color: #eef5ff;
}

a.module-card {
  text-decoration: none;
  transition: transform 160ms ease, border-color 160ms ease, background-color 160ms ease;
}

a.module-card:hover,
a.module-card:focus-visible {
  transform: translateY(-4px);
  border-color: #7cc4ff;
  outline: none;
}

.module-card-upcoming {
  border-color: rgba(137, 176, 211, 0.14);
  background: linear-gradient(145deg, rgba(15, 28, 45, 0.9), rgba(11, 21, 35, 0.9));
}

.module-card-top {
  display: flex;
  width: 100%;
  align-items: center;
  justify-content: space-between;
}

.module-icon {
  display: grid;
  width: 48px;
  height: 48px;
  place-items: center;
  border-radius: 12px;
  font-size: 30px;
}

.transit-icon {
  background: rgba(75, 163, 242, 0.16);
  color: #7cc4ff;
}

.solar-icon {
  background: rgba(242, 177, 88, 0.12);
  color: #f2b158;
}

.star-evolution-icon {
  background: rgba(242, 177, 88, 0.12);
  color: #f2c878;
}

.gravity-icon {
  background: rgba(124, 196, 255, 0.12);
  color: #8bcaff;
}

.spectra-icon {
  background: rgba(178, 145, 255, 0.14);
  color: #c1a9ff;
}

.moon-icon {
  background: rgba(182, 197, 218, 0.12);
  color: #d8deea;
}

.frontier-icon {
  background: rgba(178, 145, 255, 0.14);
  color: #c1a9ff;
}

.binary-icon {
  background: rgba(124, 196, 255, 0.14);
  color: #9ed8ff;
}

.module-status {
  font-size: 11px;
  font-weight: bold;
  letter-spacing: 0.08em;
}

.status-available {
  color: #82d9b1;
}

.status-upcoming {
  color: #f2b158;
}

.module-number {
  margin: 25px 0 8px;
  color: #8fa7bf;
  font-size: 11px;
  font-weight: bold;
  letter-spacing: 0.12em;
}

.module-card h3 {
  margin: 0;
  font-size: 22px;
}

.module-description {
  margin: 11px 0 20px;
  color: #b7c9dc;
  font-size: 15px;
  line-height: 1.6;
}

.module-action {
  display: inline-flex;
  gap: 8px;
  align-items: center;
  margin-top: auto;
  color: #7cc4ff;
  font-size: 14px;
  font-weight: bold;
}

.module-action-muted {
  color: #8fa7bf;
}

.home-footer {
  padding: 22px 0 30px;
  border-top: 1px solid rgba(183, 201, 220, 0.14);
  color: #8fa7bf;
  font-size: 13px;
  text-align: center;
}

@media (max-width: 640px) {
  .home-page main {
    width: min(100% - 32px, 480px);
  }

  .home-header {
    padding: 18px 0;
  }

  .home-hero {
    padding: 58px 0 44px;
  }

  .home-intro {
    font-size: 16px;
  }

  .section-heading {
    align-items: flex-start;
    flex-direction: column;
    gap: 8px;
  }

  .module-grid {
    grid-template-columns: 1fr;
  }

  .module-card {
    min-height: 270px;
    padding: 22px;
  }

  .top-bar {
    align-items: flex-start;
    flex-direction: column;
  }

  .top-actions {
    align-self: stretch;
    justify-content: space-between;
  }
}

/* Original handheld LCD RPG presentation for Silent Frontier. */
body.frontier-page {
  background: radial-gradient(ellipse at top, #28402c 0, #142419 52%, #0b130d 100%);
  background-attachment: fixed;
  color: #d4e5b2;
  font-family: "Courier New", Courier, monospace;
}

.frontier-page .frontier-console {
  width: min(900px, calc(100% - 28px));
  margin: 18px auto 30px;
  font-family: "Courier New", Courier, monospace;
}

.frontier-page .top-bar h1 {
  color: #d8e8b8;
  font-family: inherit;
  font-size: clamp(22px, 4vw, 34px);
  letter-spacing: 0.06em;
  text-shadow: 2px 2px 0 #203626;
}

.frontier-page .top-bar p,
.frontier-page .solar-intro,
.frontier-page .solar-intro p {
  color: #abc293;
  font-family: inherit;
  line-height: 1.55;
}

.frontier-page .back-home {
  color: #d8e8b8;
  font-family: inherit;
}

.frontier-page .solar-intro {
  max-width: 900px;
  margin: 16px 0;
  padding: 12px 14px;
  border: 2px solid #425d3d;
  background: #18291c;
}

.frontier-page .solar-intro h2,
.frontier-page .frontier-game-heading h2 {
  color: #e0edc0;
  font-family: inherit;
}

.frontier-page .solar-intro .eyebrow,
.frontier-page .frontier-game .eyebrow {
  color: #9cbb76;
  font-family: inherit;
}

.frontier-page .frontier-game.solar-panel {
  margin: 12px 0;
  padding: 12px;
  border: 4px double #526b43;
  border-radius: 8px;
  background: #18291c;
  box-shadow: 0 8px 30px rgba(0, 0, 0, 0.32), inset 0 0 0 2px #0e1a12;
  color: #d4e5b2;
  font-family: inherit;
}

.frontier-page .section-description {
  color: #abc293;
  font-family: inherit;
}

.frontier-page .frontier-stats {
  gap: 4px;
  margin: 12px 0;
  padding: 7px;
  border: 2px solid #526b43;
  background: #adbd8e;
}

.frontier-page .frontier-stat {
  min-height: 54px;
  gap: 4px;
  padding: 6px;
  border: 1px solid #78895d;
  border-radius: 0;
  background: #c6d3a7;
  color: #293d29;
  font-family: inherit;
  font-size: 11px;
}

.frontier-page .frontier-stat strong {
  color: #17291d;
  font-family: inherit;
  font-size: 18px;
}

.frontier-page .frontier-meter-group {
  gap: 5px 10px;
  padding: 8px;
  margin-bottom: 10px;
  border: 2px solid #526b43;
  background: #adbd8e;
}

.frontier-page .frontier-meter-heading {
  color: #293d29;
  font-family: inherit;
}

.frontier-page .frontier-meter-heading strong {
  color: #17291d;
  font-family: inherit;
}

.frontier-page .frontier-meter {
  height: 8px;
  border: 1px solid #78895d;
  border-radius: 0;
  background: #87966b;
}

.frontier-page .frontier-meter span {
  border-radius: 0;
  background: repeating-linear-gradient(90deg, #294a31 0 8px, #91a86d 8px 10px);
}

.frontier-page .frontier-pressure span {
  background: repeating-linear-gradient(90deg, #8c6438 0 8px, #c5a16a 8px 10px);
}

.frontier-page .frontier-map-panel,
.frontier-page .frontier-log-panel {
  padding: 9px;
  border: 3px double #718257;
  border-radius: 4px;
  background: #aebd8f;
  color: #263a28;
  font-family: inherit;
}

.frontier-page .frontier-map-heading h3,
.frontier-page .frontier-log-heading h3 {
  color: #203523;
  font-family: inherit;
  letter-spacing: 0.04em;
  text-transform: uppercase;
}

.frontier-page .frontier-map-heading > span,
.frontier-page .frontier-map-heading strong {
  color: #34492e;
  font-family: inherit;
}

.frontier-page .frontier-map-viewport {
  width: min(100%, 760px);
  margin: 8px auto 0;
  border: 3px solid #4e6540;
  border-radius: 2px;
  background: #b9c99a;
  box-shadow: inset 0 0 18px rgba(34, 55, 32, 0.22);
}

.frontier-page .frontier-starmap {
  max-height: 370px;
  image-rendering: pixelated;
}

.frontier-page .frontier-starmap .starmap-background {
  fill: #b9c99a !important;
}

.frontier-page .frontier-starmap .starmap-stars circle {
  fill: #506447 !important;
  opacity: 0.72;
}

.frontier-page .frontier-starmap .starmap-routes path:not(.target-route):not(.swarm-route) {
  stroke: #89986f !important;
  stroke-dasharray: 2 7;
  stroke-width: 2;
}

.frontier-page .frontier-starmap .target-route {
  stroke: #314e38 !important;
  stroke-width: 3;
}

.frontier-page .frontier-starmap .swarm-route {
  stroke: #8b5f3e !important;
  stroke-width: 2;
}

.frontier-page .frontier-starmap .world-target-ring {
  fill: rgba(73, 100, 54, 0.12) !important;
  stroke: transparent !important;
}

.frontier-page .frontier-starmap .frontier-world-node.is-selected .world-target-ring,
.frontier-page .frontier-starmap .frontier-world-node:focus-visible .world-target-ring {
  fill: rgba(73, 100, 54, 0.26) !important;
  stroke: #334d35 !important;
}

.frontier-page .frontier-starmap .world-orbit {
  stroke: #71855a !important;
}

.frontier-page .frontier-starmap .world-body {
  stroke: #eff0c8 !important;
  stroke-width: 2;
}

.frontier-page .frontier-starmap .world-ice { fill: #dbe4bf !important; }
.frontier-page .frontier-starmap .world-rock { fill: #ba8861 !important; }
.frontier-page .frontier-starmap .world-ocean { fill: #709b83 !important; }
.frontier-page .frontier-starmap .world-desert { fill: #d4b576 !important; }

.frontier-page .frontier-starmap .world-detail {
  stroke: #52664a !important;
}

.frontier-page .frontier-starmap .world-map-name {
  fill: #203523 !important;
  font-family: "Courier New", Courier, monospace;
  font-weight: bold;
}

.frontier-page .frontier-starmap .world-map-status {
  fill: #40563b !important;
  font-family: "Courier New", Courier, monospace;
}

.frontier-page .frontier-starmap .map-sun {
  fill: #e3bc67 !important;
  stroke: #70552e;
  stroke-width: 2;
  filter: none;
}

.frontier-page .frontier-starmap .map-sun-glow {
  opacity: 0.34;
}

.frontier-page .frontier-starmap .fleet-engine-glow {
  fill: rgba(57, 83, 47, 0.28) !important;
}

.frontier-page .frontier-starmap .map-fleet-ship {
  fill: #314e38 !important;
  filter: none;
}

.frontier-page .frontier-starmap .map-fleet-tail {
  stroke: #314e38 !important;
}

.frontier-page .frontier-starmap .starmap-home text,
.frontier-page .frontier-starmap .starmap-swarm text {
  fill: #263a28 !important;
  font-family: "Courier New", Courier, monospace;
}

.frontier-page .frontier-starmap .swarm-pulse {
  fill: rgba(139, 95, 62, 0.16) !important;
  stroke: #8b5f3e !important;
}

.frontier-page .frontier-starmap .swarm-core {
  fill: #806342 !important;
  filter: none;
}

.frontier-page .frontier-starmap .swarm-eye {
  fill: #e6d79d !important;
}

.frontier-page .frontier-map-hint {
  color: #34492e;
  font-family: inherit;
}

.frontier-page .frontier-world-select {
  border-color: #8b9b6f;
  border-radius: 0;
  background: #c3d0a3;
  color: #35472f;
  font-family: inherit;
}

.frontier-page .frontier-world-select strong {
  color: #1f3325;
  font-family: inherit;
}

.frontier-page .frontier-world-select[aria-pressed="true"] {
  border-color: #344d35;
  background: #d0d9b4;
  box-shadow: inset 3px 0 #344d35;
}

.frontier-page .frontier-command-dock {
  margin-top: 9px;
  border: 3px double #718257;
  border-radius: 3px;
  background: #18291c;
}

.frontier-page .frontier-command-heading {
  border-color: #718257;
  background: #233a29;
  color: #c4d4a1;
  font-family: inherit;
}

.frontier-page .frontier-command-heading strong {
  color: #e1edbf;
  font-family: inherit;
}

.frontier-page .frontier-command-grid {
  gap: 0;
  background: #718257;
}

.frontier-page button.frontier-command {
  min-height: 68px;
  border: 1px solid #829267;
  background: #b9c99a;
  color: #233626;
  font-family: inherit;
}

.frontier-page button.frontier-command:hover:not(:disabled),
.frontier-page button.frontier-command:focus-visible:not(:disabled) {
  background: #d3dfb3;
  outline-color: #334d35;
}

.frontier-page button.frontier-command:disabled {
  background: #919f75;
  color: #596848;
  opacity: 0.8;
}

.frontier-page .command-icon {
  border-color: #72845c;
  border-radius: 2px;
  color: #34492e;
  font-family: inherit;
}

.frontier-page .command-copy strong {
  color: #1f3325;
  font-family: inherit;
}

.frontier-page .command-copy small {
  color: #40563b;
  font-family: inherit;
}

.frontier-page .frontier-command-utility {
  border-color: #718257;
  background: #233a29;
}

.frontier-page button.frontier-reset-command {
  border-color: #829267;
  border-radius: 2px;
  background: #b9c99a;
  color: #253a28;
  font-family: inherit;
}

.frontier-page button.frontier-reset-command:hover {
  background: #d3dfb3;
  color: #17291d;
}

.frontier-page .frontier-log li {
  border-color: #526b43;
  background: #c6d3a7;
  color: #263a28;
  font-family: inherit;
}

.frontier-page .frontier-log-heading span {
  color: #40563b;
  font-family: inherit;
}

.frontier-page .frontier-outcome {
  border-color: #8b5f3e;
  border-radius: 2px;
  background: #d7c59c;
  color: #4a3823;
  font-family: inherit;
}

.frontier-page .frontier-outcome.is-victory {
  border-color: #536b44;
  background: #cfdbac;
  color: #263a28;
}

.frontier-page .frontier-console > .solar-panel:not(.frontier-game) {
  padding: 12px;
  border: 2px solid #425d3d;
  border-radius: 3px;
  background: #18291c;
}

@media (max-width: 640px) {
  .frontier-page .frontier-console {
    width: calc(100% - 20px);
    margin-top: 10px;
  }

  .frontier-page .frontier-game.solar-panel {
    padding: 8px;
  }

  .frontier-page .frontier-map-viewport {
    width: 100%;
  }

  .frontier-page .frontier-stats {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .frontier-page .frontier-command-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}

.frontier-password-screen {
  display: grid;
  min-height: 78vh;
  align-items: center;
}

.frontier-password-panel {
  width: min(440px, 100%);
  margin: 0 auto;
}

.frontier-password-panel h1 {
  margin: 0 0 12px;
  color: #eef5ff;
  font-size: clamp(26px, 5vw, 36px);
}

.frontier-password-panel form {
  display: grid;
  gap: 12px;
  margin-top: 20px;
}

.frontier-password-panel label {
  color: #c9d9eb;
}

.frontier-password-panel input {
  width: 100%;
  letter-spacing: 0.3em;
}

.frontier-password-error {
  margin: 0;
  color: #ff9e9e;
}

.frontier-password-panel > button {
  margin-top: 14px;
}

.frontier-password-actions {
  display: flex;
  align-items: center;
  gap: 10px;
  margin-top: 14px;
}

.frontier-password-actions > button {
  margin-top: 0;
}

.frontier-password-back {
  display: inline-flex;
  min-height: 42px;
  align-items: center;
  padding: 9px 14px;
  border: 1px solid #526d89;
  border-radius: 6px;
  background: rgba(18, 34, 56, 0.82);
  color: #e2effc;
  text-decoration: none;
}

.frontier-password-back:hover,
.frontier-password-back:focus-visible {
  border-color: #7cc4ff;
  background: #1b3551;
  outline: none;
}

#password-gate[hidden],
#frontier-content[hidden] {
  display: none !important;
}

* {
  box-sizing: border-box;
}
body {
  margin: 0;
  min-height: 100vh;
  font-family: Arial, sans-serif;
  background-color: #080f1d;
  background-image:
    linear-gradient(180deg, rgba(5, 11, 24, 0.83), rgba(5, 11, 24, 0.91)),
    url("images/kepler-9-transit-concept.jpg");
  background-size: cover;
  background-position: center 24%;
  background-attachment: fixed;
  color: #eef5ff;
}

main {
  width: min(900px, 92%);
  margin: 40px auto;
}

h1 {
  color: #7cc4ff;
  margin-bottom: 8px;
}

p {
  color: #b7c9dc;
}

.controls {
  display: flex;
  gap: 12px;
  align-items: end;
  flex-wrap: wrap;
  margin: 28px 0 20px;
}

label {
  display: flex;
  flex-direction: column;
  gap: 8px;
  color: #c9d9eb;
}

input {
  width: 160px;
  padding: 10px;
  border: 1px solid #52718e;
  border-radius: 6px;
  background: #122238;
  color: white;
  font-size: 16px;
}

button {
  padding: 11px 18px;
  border: 0;
  border-radius: 6px;
  background: #4ba3f2;
  color: #06111f;
  font-size: 16px;
  font-weight: bold;
  cursor: pointer;
}

button:hover {
  background: #7cc4ff;
}

#results {
  min-height: 90px;
  padding: 18px;
  margin-bottom: 20px;
  border-radius: 8px;
  background: #122238;
  color: #dcecff;
  line-height: 1.7;
}

.results-panel h2 {
  margin: 0 0 10px;
  color: #eef5ff;
  font-size: 20px;
}

.result-interpretation {
  display: inline-block;
  margin-top: 6px;
  color: #b7c9dc;
}

.result-caveat {
  margin: 8px 0 0;
  color: #9db1c6;
  font-size: 13px;
}

canvas {
  width: 100%;
  background: white;
  border-radius: 8px;
}

.top-bar {
  display: flex;
  justify-content: space-between;
  gap: 20px;
  align-items: start;
}

#language-button {
  white-space: nowrap;
}

input[type="range"] {
  width: 110px;
  padding: 0;
}

output {
  color: #7cc4ff;
  font-weight: bold;
}

.noise-inputs {
  display: flex;
  align-items: center;
  gap: 8px;
}

#noise-number {
  width: 70px;
}

.controls > label:not(.noise-control) input {
  width: 130px;
}

.simulation-action {
  display: flex;
  align-items: center;
  align-self: flex-end;
  gap: 10px;
  white-space: nowrap;
}

#simulation-status {
  color: #7cc4ff;
  font-weight: bold;
}

.observation-control {
  flex-basis: 100%;
  flex-direction: row;
  align-items: center;
  gap: 12px;
}

.observation-control input {
  width: 110px;
}

.model-note {
  margin: 0 0 22px;
  padding: 16px 18px;
  border: 1px solid #29445f;
  border-radius: 8px;
  background: #0e1b2c;
  color: #c9d9eb;
  line-height: 1.65;
}

.model-note summary {
  color: #7cc4ff;
  cursor: pointer;
  font-weight: bold;
}

.model-note p:last-child {
  margin-bottom: 0;
}

.model-note code {
  color: #eef5ff;
}

.chart-section h2 {
  margin: 0 0 12px;
  color: #eef5ff;
  font-size: 20px;
}

.visually-hidden {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}

.top-actions {
  display: flex;
  align-items: center;
  gap: 14px;
}

.back-home {
  color: #b7c9dc;
  text-decoration: none;
  white-space: nowrap;
}

.back-home:hover {
  color: #7cc4ff;
}

.home-page {
  background:
    linear-gradient(180deg, rgba(5, 11, 24, 0.38), rgba(5, 11, 24, 0.78)),
    url("images/hubble-extreme-deep-field.jpg") center 42% / cover fixed,
    #080f1d;
}

.transit-page {
  background-image:
    linear-gradient(180deg, rgba(5, 11, 24, 0.81), rgba(5, 11, 24, 0.9)),
    url("images/kepler-9-transit-concept.jpg");
  background-position: center 20%;
}

.image-credit {
  color: #a9bbcf;
  font-size: 12px;
  line-height: 1.5;
  text-decoration: none;
}

.image-credit:hover {
  color: #d8e9fa;
  text-decoration: underline;
}

.page-image-credit {
  padding: 22px 0 30px;
  text-align: right;
}

.home-footer p {
  margin: 0 0 8px;
}

.home-footer .image-credit {
  display: inline-block;
  max-width: 100%;
  text-align: center;
}

.solar-page {
  background:
    linear-gradient(180deg, rgba(5, 11, 24, 0.7), rgba(5, 11, 24, 0.83)),
    url("images/solar-system-eight-planets.jpg") center 28% / cover fixed,
    #080f1d;
  background-attachment: fixed;
}

.moon-page {
  background:
    linear-gradient(180deg, rgba(5, 11, 24, 0.72), rgba(5, 11, 24, 0.88)),
    url("images/solar-system-eight-planets.jpg") center 28% / cover fixed,
    #080f1d;
}

.moon-main {
  width: min(900px, 92%);
  margin: 34px auto 0;
}

.moon-intro {
  max-width: 720px;
  margin: 34px 0 24px;
  color: #c1d2e3;
  line-height: 1.7;
}

.moon-intro h2 {
  margin: 0;
  color: #eef5ff;
  font-size: clamp(25px, 4vw, 34px);
}

.moon-intro > p:last-child {
  margin-bottom: 0;
}

.moon-day-badge {
  flex: 0 0 auto;
  padding: 8px 12px;
  border: 1px solid rgba(137, 176, 211, 0.24);
  border-radius: 999px;
  color: #b7c9dc;
  font-size: 13px;
}

.moon-day-badge strong {
  color: #eef5ff;
  font-variant-numeric: tabular-nums;
}

.moon-visual {
  margin: 18px auto 10px;
  overflow: hidden;
  border: 1px solid rgba(119, 157, 193, 0.14);
  border-radius: 14px;
  background: radial-gradient(ellipse at center, rgba(29, 56, 84, 0.58), rgba(6, 14, 26, 0.88) 72%);
}

.moon-orbit-svg {
  display: block;
  width: 100%;
  height: auto;
}

.moon-orbit-svg text {
  fill: #c9d9eb;
  font-family: Arial, sans-serif;
  font-size: 13px;
}

.sun-direction path {
  fill: none;
  stroke: #f2b158;
  stroke-width: 2;
}

.moon-orbit-track {
  fill: none;
  stroke: rgba(164, 191, 216, 0.42);
  stroke-dasharray: 4 7;
  stroke-width: 1.5;
}

.earth-body {
  stroke: rgba(171, 222, 255, 0.8);
  stroke-width: 1.5;
}

.earth-label {
  font-weight: bold;
}

.orbiting-moon circle:first-child {
  stroke: rgba(255, 255, 255, 0.65);
  stroke-width: 1;
}

.tidal-bulge ellipse {
  fill: rgba(74, 162, 218, 0.2);
  stroke: rgba(124, 196, 255, 0.86);
  stroke-width: 1.5;
  stroke-dasharray: 4 3;
  transition: rx 120ms ease, transform 120ms ease;
}

.tidal-bulge circle {
  fill: #a8dfff;
  filter: drop-shadow(0 0 4px rgba(124, 196, 255, 0.9));
}

.orbit-moon-shadow,
.moon-disc-shadow {
  fill: #111824;
}

.moon-orbit-label {
  fill: #91a9c1 !important;
  font-size: 11px !important;
}

.moon-phase-summary {
  display: flex;
  align-items: center;
  gap: 18px;
  width: fit-content;
  margin: 22px auto;
}

.moon-phase-disc {
  width: 92px;
  height: 92px;
  flex: 0 0 auto;
  filter: drop-shadow(0 0 18px rgba(236, 231, 208, 0.15));
}

.moon-phase-disc svg {
  display: block;
  width: 100%;
  height: 100%;
}

.moon-disc-lit {
  fill: #e9e5d8;
}

.moon-phase-summary .eyebrow {
  margin-bottom: 5px;
}

.moon-phase-summary h3 {
  margin: 0;
  color: #f0f6fc;
  font-size: 21px;
}

.phase-illumination-text {
  margin: 6px 0 0;
  color: #a9bbcf;
  font-size: 14px;
}

.phase-illumination-text strong {
  color: #f0f6fc;
  font-variant-numeric: tabular-nums;
}

.moon-time-control {
  display: flex;
  flex-direction: column;
  gap: 10px;
  margin-top: 24px;
  color: #c9d9eb;
  font-weight: bold;
}

.moon-time-control input[type="range"] {
  width: 100%;
  accent-color: #7cc4ff;
}

.moon-range-labels {
  display: flex;
  justify-content: space-between;
  gap: 8px;
  color: #9fb4c9;
  font-size: 11px;
  font-weight: normal;
}

.moon-facts-grid {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 10px;
  margin: 18px 0 0;
}

.moon-facts-grid > div {
  min-width: 0;
  padding: 13px;
  border: 1px solid rgba(137, 176, 211, 0.14);
  border-radius: 10px;
  background: rgba(5, 13, 25, 0.42);
}

.moon-facts-grid dt {
  margin-bottom: 7px;
  color: #91a9c1;
  font-size: 12px;
  line-height: 1.5;
}

.moon-facts-grid dd {
  margin: 0;
  color: #f0f6fc;
  font-size: 15px;
  font-weight: bold;
  line-height: 1.45;
}

.moon-explanation {
  margin: 16px 0 0;
  color: #c1d2e3;
  font-size: 14px;
  line-height: 1.7;
}

.binary-page {
  background-image:
    radial-gradient(ellipse at 50% 18%, rgba(32, 60, 93, 0.42), transparent 55%),
    linear-gradient(180deg, rgba(5, 11, 24, 0.84), rgba(5, 11, 24, 0.94)),
    url("images/hubble-extreme-deep-field.jpg");
  background-position: center top;
}

.binary-main {
  width: min(1080px, 92%);
  margin: 36px auto;
}

.binary-intro {
  max-width: 820px;
  margin: 34px 0 24px;
  line-height: 1.7;
}

.binary-intro h2,
.binary-explanation h2 {
  margin: 0;
  color: #eef5ff;
  font-size: clamp(24px, 4vw, 34px);
}

.binary-intro > p:last-child,
.binary-explanation > p:not(.eyebrow) {
  color: #b7c9dc;
  line-height: 1.75;
}

.binary-panel,
.binary-explanation {
  margin-top: 18px;
  padding: 26px;
  border: 1px solid rgba(124, 196, 255, 0.2);
  border-radius: 14px;
  background: linear-gradient(145deg, rgba(18, 34, 56, 0.88), rgba(9, 20, 35, 0.9));
}

.binary-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}

.binary-actions .secondary-button {
  white-space: nowrap;
}

.binary-controls {
  display: grid;
  grid-template-columns: minmax(160px, 1fr) minmax(220px, 1.4fr) minmax(180px, 1fr);
  gap: 14px;
  margin: 22px 0 16px;
}

.binary-control {
  min-width: 0;
  gap: 8px;
  color: #c9d9eb;
  font-size: 13px;
}

.binary-control select {
  width: 100%;
  min-height: 42px;
  padding: 9px 30px 9px 11px;
  border: 1px solid #52718e;
  border-radius: 7px;
  background: #122238;
  color: #eef5ff;
  font: inherit;
}

.binary-speed-control input[type="range"] {
  width: 100%;
  accent-color: #7cc4ff;
}

.binary-speed-control output {
  margin-left: 5px;
  font-variant-numeric: tabular-nums;
}

.gravity-vector-toggle {
  display: flex;
  flex-direction: row;
  align-items: flex-start;
  gap: 10px;
  margin: 4px 0 16px;
  color: #c9d9eb;
  cursor: pointer;
}

.gravity-vector-toggle input {
  width: 17px;
  height: 17px;
  flex: 0 0 auto;
  margin: 1px 0 0;
  accent-color: #7cc4ff;
}

.gravity-vector-toggle span {
  display: grid;
  gap: 4px;
}

.gravity-vector-toggle strong {
  color: #dcecff;
  font-size: 13px;
}

.gravity-vector-toggle small {
  color: #91a9c1;
  font-size: 12px;
  line-height: 1.5;
}

.mass-control-panel {
  margin: 0 0 18px;
  padding: 15px;
  border: 1px solid rgba(137, 176, 211, 0.17);
  border-radius: 10px;
  background: rgba(5, 13, 25, 0.34);
}

.mass-control-heading {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 14px;
  margin-bottom: 12px;
}

.mass-control-heading h3 {
  margin: 0;
  color: #dcecff;
  font-size: 14px;
}

.mass-control-heading p {
  margin: 5px 0 0;
  color: #91a9c1;
  font-size: 12px;
  line-height: 1.5;
}

.mass-control-heading > span {
  flex: 0 0 auto;
  color: #91a9c1;
  font-size: 11px;
}

.mass-controls {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(190px, 1fr));
  gap: 10px 16px;
}

.mass-control {
  min-width: 0;
  gap: 8px;
  color: #c9d9eb;
  font-size: 12px;
}

.mass-control-label {
  display: flex;
  align-items: center;
  gap: 7px;
}

.mass-control-label i {
  width: 9px;
  height: 9px;
  flex: 0 0 auto;
  border-radius: 50%;
  background: var(--star-color);
  box-shadow: 0 0 8px var(--star-color);
}

.mass-control output {
  margin-left: auto;
  color: #eef5ff;
  font-size: 12px;
  font-variant-numeric: tabular-nums;
}

.mass-control input[type="range"] {
  width: 100%;
  margin: 0;
  accent-color: #7cc4ff;
}

.binary-visual {
  overflow: hidden;
  border: 1px solid rgba(119, 157, 193, 0.18);
  border-radius: 12px;
  background: radial-gradient(ellipse at center, rgba(32, 62, 92, 0.45), rgba(4, 11, 21, 0.92) 75%);
}

.binary-visual canvas {
  display: block;
  width: 100%;
  height: auto;
  aspect-ratio: 5 / 3;
  background: transparent;
  border-radius: 0;
}

.star-legend {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
  margin-top: 14px;
}

.star-legend-item {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  padding: 7px 10px;
  border: 1px solid rgba(137, 176, 211, 0.16);
  border-radius: 999px;
  color: #c9d9eb;
  font-size: 12px;
}

.star-legend-item i {
  width: 9px;
  height: 9px;
  border-radius: 50%;
  background: var(--star-color);
  box-shadow: 0 0 9px var(--star-color);
}

.star-legend-item strong {
  color: #eef5ff;
  font-variant-numeric: tabular-nums;
}

.binary-stats {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 10px;
  margin: 16px 0 0;
}

.binary-stats > div {
  padding: 12px 14px;
  border: 1px solid rgba(137, 176, 211, 0.14);
  border-radius: 10px;
  background: rgba(5, 13, 25, 0.38);
}

.binary-stats dt {
  color: #91a9c1;
  font-size: 12px;
}

.binary-stats dd {
  margin: 6px 0 0;
  color: #eef5ff;
  font-size: 15px;
  font-weight: bold;
  font-variant-numeric: tabular-nums;
}

.binary-explanation .model-note {
  margin-top: 18px;
}

.binary-main .solar-footer {
  padding-bottom: 32px;
}

.binary-page button:focus-visible,
.binary-page select:focus-visible,
.binary-page input:focus-visible {
  outline: 2px solid #a4d7ff;
  outline-offset: 3px;
}

.tide-status {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 24px;
  margin-top: 20px;
  padding: 16px;
  border: 1px solid rgba(137, 176, 211, 0.16);
  border-radius: 12px;
  background: rgba(5, 13, 25, 0.38);
}

.tide-state-label {
  margin: 0 0 5px;
  color: #9fb4c9;
  font-size: 12px;
}

.tide-status h3 {
  margin: 0;
  color: #f0f6fc;
  font-size: 19px;
}

.tide-strength {
  width: min(320px, 52%);
}

.tide-strength-heading {
  display: flex;
  justify-content: space-between;
  gap: 12px;
  margin-bottom: 8px;
  color: #a9bbcf;
  font-size: 12px;
}

.tide-strength-heading strong {
  color: #f0f6fc;
  font-variant-numeric: tabular-nums;
}

.tide-strength-track {
  height: 9px;
  overflow: hidden;
  border-radius: 999px;
  background: rgba(137, 176, 211, 0.16);
}

.tide-strength-track span {
  display: block;
  width: 100%;
  height: 100%;
  border-radius: inherit;
  background: linear-gradient(90deg, #4ba3f2, #83d8dc);
  transition: width 140ms ease;
}

.tide-types {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 12px;
  margin-top: 18px;
}

.tide-types article {
  padding: 14px;
  border: 1px solid rgba(137, 176, 211, 0.14);
  border-radius: 10px;
  background: rgba(5, 13, 25, 0.32);
}

.tide-types h3 {
  margin: 0 0 7px;
  color: #dcecff;
  font-size: 15px;
}

.tide-types p {
  margin: 0;
  color: #b7c9dc;
  font-size: 13px;
  line-height: 1.6;
}

.tide-model-note {
  margin: 18px 0 0;
}

.solar-main {
  width: min(1000px, 92%);
  margin: 34px auto 0;
}

.solar-intro {
  max-width: 720px;
  margin: 34px 0 24px;
  color: #c1d2e3;
  font-size: 17px;
  line-height: 1.7;
}

.solar-intro p:last-child {
  margin-bottom: 0;
}

.solar-panel {
  margin: 18px 0;
  padding: 24px;
  border: 1px solid rgba(137, 176, 211, 0.2);
  border-radius: 16px;
  background: linear-gradient(145deg, rgba(14, 28, 47, 0.94), rgba(9, 19, 34, 0.94));
  box-shadow: 0 18px 55px rgba(0, 0, 0, 0.16);
}

.solar-section-heading {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 18px;
}

.solar-section-heading .eyebrow,
.solar-panel > .eyebrow {
  margin-bottom: 7px;
}

.solar-panel h2 {
  margin: 0;
  color: #eef5ff;
  font-size: clamp(21px, 3vw, 27px);
}

.section-description {
  max-width: 760px;
  margin: 12px 0 0;
  color: #9fb4c9;
  font-size: 14px;
  line-height: 1.65;
}

.secondary-button {
  flex: 0 0 auto;
  border: 1px solid #526d89;
  background: rgba(18, 34, 56, 0.82);
  color: #e2effc;
}

.secondary-button:hover {
  background: #1b3551;
}

.orbit-visual {
  overflow: hidden;
  margin: 18px auto 8px;
  border: 1px solid rgba(119, 157, 193, 0.14);
  border-radius: 14px;
  background:
    radial-gradient(ellipse at center, rgba(29, 56, 84, 0.58), rgba(6, 14, 26, 0.88) 72%);
}

.orbit-svg {
  display: block;
  width: 100%;
  height: auto;
  max-height: 620px;
}

.orbit-tracks circle {
  fill: none;
  stroke: rgba(164, 191, 216, 0.24);
  stroke-width: 1.25;
  stroke-dasharray: 3 6;
}

.sun-glow {
  fill: url(#sun-glow);
}

.sun-core {
  fill: #fff4c2;
  filter: drop-shadow(0 0 9px rgba(255, 196, 94, 0.9));
}

.sun-hit-area {
  fill: transparent;
  cursor: pointer;
}

.sun-select:focus-visible {
  outline: none;
}

.sun-select:focus-visible .sun-core {
  stroke: #ffffff;
  stroke-width: 3;
}

.orbit-motion {
  transform-box: view-box;
  transform-origin: 400px 325px;
  animation: orbit-revolution var(--orbit-duration) linear infinite;
}

.orbit-motion circle {
  stroke: rgba(255, 255, 255, 0.6);
  stroke-width: 1;
  transition: filter 180ms ease, stroke-width 180ms ease;
}

.orbit-motion.mercury-orbit circle { fill: #aaa39b; }
.orbit-motion.venus-orbit circle { fill: #e6b875; }
.orbit-motion.earth-orbit circle { fill: #61a9f2; }
.orbit-motion.mars-orbit circle { fill: #e37b58; }
.orbit-motion.jupiter-orbit circle { fill: #dfa779; }
.orbit-motion.saturn-orbit circle { fill: #e8cd87; }
.orbit-motion.uranus-orbit circle { fill: #81d5dc; }
.orbit-motion.neptune-orbit circle { fill: #5d84ee; }

.saturn-rings {
  fill: none;
  stroke: #eed89f;
  stroke-width: 2.5;
}

.orbit-visual.is-paused .orbit-motion {
  animation-play-state: paused;
}

.orbit-visual[data-selected="mercury"] .mercury-orbit circle,
.orbit-visual[data-selected="venus"] .venus-orbit circle,
.orbit-visual[data-selected="earth"] .earth-orbit circle,
.orbit-visual[data-selected="mars"] .mars-orbit circle,
.orbit-visual[data-selected="jupiter"] .jupiter-orbit circle,
.orbit-visual[data-selected="saturn"] .saturn-orbit circle,
.orbit-visual[data-selected="uranus"] .uranus-orbit circle,
.orbit-visual[data-selected="neptune"] .neptune-orbit circle {
  filter: drop-shadow(0 0 8px currentColor);
  stroke: #ffffff;
  stroke-width: 2;
}

.orbit-visual[data-selected="sun"] .sun-core {
  stroke: #ffffff;
  stroke-width: 2;
  filter: drop-shadow(0 0 14px rgba(255, 208, 105, 1));
}

@keyframes orbit-revolution {
  from { transform: rotate(0deg); }
  to { transform: rotate(360deg); }
}

.planet-picker {
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  gap: 8px;
  margin-top: 16px;
}

.planet-choice {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 8px 12px;
  border: 1px solid rgba(137, 176, 211, 0.24);
  border-radius: 999px;
  background: rgba(8, 17, 31, 0.64);
  color: #c9d9eb;
  font-size: 14px;
  font-weight: normal;
}

.planet-choice:hover,
.planet-choice.is-selected {
  border-color: #7cc4ff;
  background: rgba(46, 93, 137, 0.4);
  color: #fff;
}

.planet-choice:focus-visible,
.size-planet:focus-visible,
.secondary-button:focus-visible {
  outline: 2px solid #a4d7ff;
  outline-offset: 3px;
}

.planet-swatch {
  width: 10px;
  height: 10px;
  flex: 0 0 auto;
  border-radius: 50%;
}

.sun-swatch { background: #ffc45e; box-shadow: 0 0 8px rgba(255, 196, 94, 0.8); }
.mercury-swatch { background: #aaa39b; }
.venus-swatch { background: #e6b875; }
.earth-swatch { background: #61a9f2; }
.mars-swatch { background: #e37b58; }
.jupiter-swatch { background: #dfa779; }
.saturn-swatch { background: #e8cd87; }
.uranus-swatch { background: #81d5dc; }
.neptune-swatch { background: #5d84ee; }

.planet-detail-panel {
  border-color: rgba(124, 196, 255, 0.3);
}

.detail-heading {
  align-items: flex-end;
}

.planet-type {
  padding: 6px 11px;
  border: 1px solid rgba(124, 196, 255, 0.24);
  border-radius: 999px;
  color: #9ecbf0;
  font-size: 13px;
}

.planet-fact {
  max-width: 800px;
  margin: 15px 0 20px;
  color: #c4d6e8;
  line-height: 1.7;
}

.planet-stats {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 10px;
  margin: 0;
}

.planet-stats > div {
  min-width: 0;
  padding: 13px;
  border: 1px solid rgba(137, 176, 211, 0.14);
  border-radius: 10px;
  background: rgba(5, 13, 25, 0.42);
}

.planet-stats dt {
  margin-bottom: 7px;
  color: #91a9c1;
  font-size: 12px;
  line-height: 1.5;
}

.planet-stats dd {
  margin: 0;
  color: #f0f6fc;
  font-size: 15px;
  font-weight: bold;
  line-height: 1.45;
  overflow-wrap: anywhere;
}

.unit-note {
  margin: 12px 0 0;
  color: #8fa7bf;
  font-size: 12px;
  line-height: 1.6;
}

.kepler-result {
  margin: 16px 0 0;
  padding: 12px 14px;
  border-left: 3px solid #f2b158;
  background: rgba(242, 177, 88, 0.08);
  color: #d7e3ef;
  font-size: 13px;
  line-height: 1.7;
}

.kepler-result strong {
  color: #f5c879;
}

.kepler-result-note {
  border-left-color: #ffc45e;
}

.size-comparison {
  display: grid;
  grid-template-columns: repeat(8, minmax(0, 1fr));
  gap: 8px;
  align-items: stretch;
  margin-top: 20px;
}

.size-planet {
  display: flex;
  min-width: 0;
  flex-direction: column;
  align-items: center;
  justify-content: flex-end;
  gap: 6px;
  padding: 12px 5px;
  border: 1px solid transparent;
  border-radius: 10px;
  background: rgba(5, 13, 25, 0.32);
  color: #c9d9eb;
  font-size: 12px;
  font-weight: normal;
}

.size-planet:hover,
.size-planet.is-selected {
  border-color: rgba(124, 196, 255, 0.52);
  background: rgba(46, 93, 137, 0.28);
}

.size-orb {
  display: block;
  width: var(--planet-size);
  height: var(--planet-size);
  flex: 0 0 auto;
  border: 1px solid rgba(255, 255, 255, 0.42);
  border-radius: 50%;
  box-shadow: inset -5px -4px 9px rgba(0, 0, 0, 0.28), 0 0 12px rgba(108, 166, 220, 0.14);
}

.size-planet-name {
  margin-top: 8px;
  color: #eef5ff;
  font-weight: bold;
}

.size-planet-value,
.size-earth-ratio {
  color: #a9bbcf;
  font-size: 10px;
  text-align: center;
}

.planet-comparison {
  margin-top: 28px;
  padding-top: 22px;
  border-top: 1px solid rgba(137, 176, 211, 0.18);
}

.planet-comparison h3 {
  margin: 0;
  color: #eef5ff;
  font-size: 18px;
}

.comparison-picker {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin-top: 14px;
}

.comparison-planet {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 8px 12px;
  border: 1px solid rgba(137, 176, 211, 0.24);
  border-radius: 999px;
  background: rgba(8, 17, 31, 0.64);
  color: #c9d9eb;
  font-size: 14px;
  font-weight: normal;
}

.comparison-planet:hover,
.comparison-planet.is-selected {
  border-color: #7cc4ff;
  background: rgba(46, 93, 137, 0.4);
  color: #fff;
}

.comparison-planet:focus-visible {
  outline: 2px solid #a4d7ff;
  outline-offset: 3px;
}

.comparison-results {
  margin-top: 16px;
}

.comparison-empty {
  margin: 0;
  color: #a9bbcf;
  font-size: 13px;
}

.comparison-table-wrap {
  overflow-x: auto;
  border: 1px solid rgba(137, 176, 211, 0.18);
  border-radius: 10px;
}

.comparison-table {
  width: 100%;
  min-width: 480px;
  border-collapse: collapse;
  text-align: left;
}

.comparison-table th,
.comparison-table td {
  padding: 11px 13px;
  border-bottom: 1px solid rgba(137, 176, 211, 0.14);
  color: #dce9f6;
  font-size: 13px;
  line-height: 1.5;
  vertical-align: top;
}

.comparison-table thead th {
  background: rgba(46, 93, 137, 0.2);
  color: #f0f6fc;
}

.comparison-table tbody th {
  width: 26%;
  color: #91a9c1;
  font-weight: normal;
}

.comparison-table tbody tr:last-child th,
.comparison-table tbody tr:last-child td {
  border-bottom: 0;
}

.comparison-planet-heading {
  display: inline-flex;
  align-items: center;
  gap: 8px;
}

.kepler-panel > p:not(.eyebrow) {
  color: #c1d2e3;
  line-height: 1.75;
}

.kepler-panel .book-reference {
  margin-bottom: 0;
  color: #91a9c1;
  font-size: 13px;
}

.solar-footer {
  display: flex;
  flex-wrap: wrap;
  justify-content: space-between;
  gap: 8px 20px;
  padding: 18px 0 32px;
}

@media (prefers-reduced-motion: reduce) {
  .orbit-visual:not(.motion-enabled) .orbit-motion {
    animation: none;
  }
}

@media (max-width: 640px) {
  .binary-page {
    background-attachment: scroll;
  }

  .binary-main {
    width: min(100% - 28px, 520px);
    margin-top: 22px;
  }

  .binary-panel,
  .binary-explanation {
    padding: 18px 14px;
  }

  .binary-controls {
    grid-template-columns: 1fr;
    gap: 12px;
  }

  .mass-control-heading {
    flex-direction: column;
    gap: 7px;
  }

  .mass-controls {
    grid-template-columns: 1fr;
  }

  .binary-stats {
    grid-template-columns: 1fr;
  }

  .binary-visual canvas {
    min-height: 240px;
  }

  .solar-page {
    background-attachment: scroll;
  }

  .moon-page {
    background-attachment: scroll;
  }

  .solar-main {
    width: min(100% - 28px, 520px);
    margin-top: 22px;
  }

  .moon-main {
    width: min(100% - 28px, 520px);
    margin-top: 22px;
  }

  .moon-intro {
    margin-top: 24px;
    font-size: 15px;
  }

  .solar-intro {
    margin-top: 24px;
    font-size: 15px;
  }

  .solar-panel {
    padding: 18px 14px;
  }

  .moon-day-badge {
    align-self: flex-start;
  }

  .moon-facts-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .moon-range-labels {
    font-size: 10px;
  }

  .tide-status {
    align-items: stretch;
    flex-direction: column;
    gap: 14px;
  }

  .tide-strength {
    width: 100%;
  }

  .tide-types {
    grid-template-columns: 1fr;
  }

  .solar-section-heading {
    align-items: flex-start;
    flex-direction: column;
  }

  .orbit-svg {
    width: 100%;
    max-width: 100%;
  }

  .orbit-visual {
    height: auto;
  }

  .planet-stats {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .size-comparison {
    grid-template-columns: repeat(4, minmax(0, 1fr));
  }

  .solar-footer {
    flex-direction: column;
  }
}

.frontier-game-heading,
.frontier-log-heading {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
}

.frontier-game-heading h2 {
  margin: 0;
  color: #eef5ff;
  font-size: clamp(22px, 3vw, 29px);
}

.frontier-stats {
  display: grid;
  grid-template-columns: repeat(5, minmax(0, 1fr));
  gap: 10px;
  margin: 24px 0;
}

.frontier-stat {
  display: flex;
  min-height: 75px;
  flex-direction: column;
  justify-content: space-between;
  gap: 8px;
  padding: 13px;
  border: 1px solid rgba(137, 176, 211, 0.18);
  border-radius: 10px;
  background: rgba(7, 17, 31, 0.68);
  color: #9fb4c9;
  font-size: 12px;
}

.frontier-stat strong {
  color: #eef5ff;
  font-size: 20px;
}

.frontier-meter-group {
  display: grid;
  grid-template-columns: 1fr auto;
  gap: 8px 12px;
  align-items: center;
  margin-bottom: 22px;
}

.frontier-meter-heading {
  display: contents;
  color: #b7c9dc;
  font-size: 13px;
}

.frontier-meter-heading strong {
  color: #eef5ff;
}

.frontier-meter {
  overflow: hidden;
  height: 9px;
  grid-column: 1 / -1;
  border-radius: 99px;
  background: #091321;
}

.frontier-meter span {
  display: block;
  width: 12%;
  height: 100%;
  border-radius: inherit;
  background: linear-gradient(90deg, #55bd9a, #f0b452, #eb6b62);
  transition: width 180ms ease;
}

.frontier-pressure span {
  background: linear-gradient(90deg, #7cc4ff, #b078e6, #eb6b62);
}

.frontier-map-panel,
.frontier-log-panel {
  padding: 16px;
  border: 1px solid rgba(137, 176, 211, 0.16);
  border-radius: 12px;
  background: rgba(7, 17, 31, 0.55);
}

.frontier-map-heading {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
}

.frontier-map-heading h3 {
  margin: 0;
  color: #eef5ff;
  font-size: 16px;
}

.frontier-map-heading > span {
  color: #9fb4c9;
  font-size: 12px;
}

.frontier-map-heading strong {
  color: #7cc4ff;
}

.frontier-map-viewport {
  overflow: hidden;
  margin-top: 13px;
  border: 1px solid rgba(124, 196, 255, 0.16);
  border-radius: 12px;
  background: #07111f;
}

.frontier-starmap {
  display: block;
  width: 100%;
  height: auto;
  min-height: 230px;
}

.starmap-background {
  fill: #07111f;
}

.starmap-stars circle {
  fill: #cde6ff;
  opacity: 0.65;
  animation: star-twinkle 3.8s ease-in-out infinite;
}

.starmap-stars circle:nth-child(3n) {
  animation-delay: -1.5s;
}

.starmap-stars circle:nth-child(2n) {
  animation-delay: -2.4s;
}

.starmap-routes path {
  fill: none;
  stroke: rgba(124, 196, 255, 0.34);
  stroke-dasharray: 4 8;
  stroke-width: 1.5;
}

.starmap-routes .swarm-route {
  stroke: rgba(235, 107, 98, 0.62);
  stroke-dasharray: 3 7;
  animation: route-drift 7s linear infinite;
}

.frontier-world-node {
  cursor: pointer;
  outline: none;
}

.world-target-ring {
  fill: rgba(124, 196, 255, 0.02);
  stroke: transparent;
  stroke-width: 2;
  transition: fill 150ms ease, stroke 150ms ease;
}

.world-orbit {
  fill: none;
  stroke: rgba(160, 192, 220, 0.44);
  stroke-dasharray: 3 5;
  stroke-width: 1;
  animation: orbit-drift 14s linear infinite;
}

.world-body {
  stroke: rgba(225, 240, 255, 0.8);
  stroke-width: 1.5;
}

.world-ice {
  fill: #b9d6e8;
}

.world-rock {
  fill: #bb8464;
}

.world-ocean {
  fill: #337faa;
}

.world-desert {
  fill: #d5a958;
}

.world-detail {
  fill: none;
  stroke: rgba(8, 18, 32, 0.6);
  stroke-linecap: round;
  stroke-width: 2;
}

.colony-marker {
  display: none;
  fill: #82d9b1;
  stroke: #07111f;
  stroke-width: 1.5;
}

.frontier-world-node.is-colonized .colony-marker {
  display: block;
}

.world-map-name,
.world-map-status {
  fill: #dcecff;
  font-family: Arial, sans-serif;
  font-size: 10px;
  font-weight: bold;
  letter-spacing: 0.07em;
  pointer-events: none;
  text-anchor: middle;
}

.world-map-status {
  fill: #8fa7bf;
  font-size: 8px;
  font-weight: normal;
  letter-spacing: 0.02em;
}

.frontier-world-node.is-undiscovered .world-body {
  filter: grayscale(0.7);
  opacity: 0.64;
}

.frontier-world-node.is-selected .world-target-ring,
.frontier-world-node:hover .world-target-ring,
.frontier-world-node:focus-visible .world-target-ring {
  fill: rgba(124, 196, 255, 0.12);
  stroke: #7cc4ff;
}

.frontier-world-node.is-colonized .world-target-ring {
  stroke: #82d9b1;
}

.map-sun {
  fill: #ffe7a3;
  filter: drop-shadow(0 0 8px rgba(242, 177, 88, 0.9));
  transform-box: fill-box;
  transform-origin: center;
  animation: sun-pulse 3s ease-in-out infinite;
}

.fleet-engine-glow {
  fill: rgba(124, 196, 255, 0.22);
  transform-box: fill-box;
  transform-origin: center;
  animation: engine-pulse 450ms ease-in-out infinite alternate;
}

.map-fleet-ship,
.map-fleet-tail {
  pointer-events: none;
}

.map-fleet-ship {
  fill: #7cc4ff;
  filter: drop-shadow(0 0 5px rgba(124, 196, 255, 0.9));
}

.map-fleet-tail {
  fill: none;
  stroke: #b7e4ff;
  stroke-linecap: round;
  stroke-width: 2;
}

.starmap-home text,
.starmap-swarm text {
  fill: #b7c9dc;
  font-family: Arial, sans-serif;
  font-size: 9px;
  font-weight: bold;
  letter-spacing: 0.12em;
  text-anchor: middle;
}

.swarm-pulse {
  fill: rgba(235, 107, 98, 0.06);
  stroke: rgba(235, 107, 98, 0.34);
  stroke-width: 1;
  animation: swarm-pulse 2.8s ease-in-out infinite;
}

.swarm-core {
  fill: #d96f71;
  filter: drop-shadow(0 0 8px rgba(235, 107, 98, 0.55));
  transform-box: fill-box;
  transform-origin: center;
  animation: swarm-turn 18s linear infinite;
}

.starmap-swarm {
  transition: transform 700ms cubic-bezier(0.2, 0.8, 0.25, 1);
}

.starmap-swarm.is-attacking .swarm-core {
  fill: #ff9a84;
  filter: drop-shadow(0 0 16px rgba(255, 104, 92, 0.95));
}

.target-route {
  stroke: rgba(124, 196, 255, 0.92) !important;
  stroke-dasharray: 2 7 !important;
  animation: route-drift 900ms linear infinite !important;
}

.swarm-eye {
  fill: #ffe1b4;
}

.frontier-map-hint {
  margin: 10px 0 0;
  color: #8fa7bf;
  font-size: 12px;
  line-height: 1.5;
}

.frontier-command-dock {
  margin-top: 15px;
  overflow: hidden;
  border: 1px solid rgba(124, 196, 255, 0.24);
  border-radius: 11px;
  background: linear-gradient(145deg, rgba(15, 31, 51, 0.96), rgba(8, 19, 33, 0.97));
}

.frontier-command-heading {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 11px 13px;
  border-bottom: 1px solid rgba(137, 176, 211, 0.14);
  color: #9fb4c9;
  font-size: 12px;
  letter-spacing: 0.06em;
  text-transform: uppercase;
}

.frontier-command-heading strong {
  color: #7cc4ff;
  letter-spacing: 0;
  text-transform: none;
}

.frontier-command-grid {
  display: grid;
  grid-template-columns: repeat(5, minmax(0, 1fr));
  gap: 1px;
  background: rgba(137, 176, 211, 0.13);
}

.frontier-command-utility {
  display: flex;
  justify-content: flex-end;
  gap: 8px;
  padding: 8px 10px;
  border-top: 1px solid rgba(137, 176, 211, 0.14);
  background: rgba(7, 17, 31, 0.92);
}

button.frontier-reset-command {
  display: inline-flex;
  min-height: 34px;
  align-items: center;
  justify-content: center;
  gap: 7px;
  padding: 7px 11px;
  border: 1px solid rgba(124, 196, 255, 0.24);
  border-radius: 7px;
  background: rgba(18, 34, 56, 0.92);
  color: #b7c9dc;
  font-size: 12px;
}

button.frontier-reset-command:hover {
  border-color: #7cc4ff;
  background: #17314e;
  color: #eef5ff;
}

button.frontier-language-command {
  min-width: 74px;
  color: #7cc4ff;
}

button.frontier-command {
  display: flex;
  min-width: 0;
  min-height: 86px;
  align-items: flex-start;
  gap: 9px;
  padding: 13px 10px;
  border: 0;
  border-radius: 0;
  background: rgba(8, 19, 33, 0.98);
  color: #eef5ff;
  text-align: left;
  transition: background-color 150ms ease, color 150ms ease;
}

button.frontier-command:hover:not(:disabled),
button.frontier-command:focus-visible:not(:disabled) {
  background: #17314e;
  outline: 1px solid #7cc4ff;
  outline-offset: -2px;
}

button.frontier-command:disabled {
  background: rgba(8, 19, 33, 0.78);
  color: #8295a9;
  cursor: not-allowed;
  opacity: 0.6;
}

.command-icon {
  display: grid;
  width: 27px;
  height: 27px;
  flex: 0 0 27px;
  place-items: center;
  border: 1px solid rgba(124, 196, 255, 0.3);
  border-radius: 7px;
  color: #7cc4ff;
  font-size: 17px;
}

.command-copy {
  display: grid;
  min-width: 0;
  gap: 6px;
}

.command-copy strong {
  font-size: 12px;
  line-height: 1.3;
}

.command-copy small {
  color: #91a8be;
  font-size: 10px;
  font-weight: normal;
  line-height: 1.4;
}

@keyframes swarm-pulse {
  0%, 100% { opacity: 0.38; }
  50% { opacity: 1; }
}

@keyframes route-drift {
  to { stroke-dashoffset: -40; }
}

@keyframes star-twinkle {
  0%, 100% { opacity: 0.3; }
  50% { opacity: 0.95; }
}

@keyframes orbit-drift {
  to { stroke-dashoffset: -32; }
}

@keyframes sun-pulse {
  0%, 100% { opacity: 0.82; }
  50% { opacity: 1; }
}

@keyframes engine-pulse {
  to { opacity: 0.4; transform: scale(1.2); }
}

@keyframes swarm-turn {
  to { transform: rotate(360deg); }
}

.frontier-log-heading h3 {
  margin: 0;
  color: #eef5ff;
  font-size: 16px;
}

.frontier-world-list,
.frontier-log {
  display: grid;
  gap: 8px;
  padding: 0;
  margin: 13px 0 0;
  list-style: none;
}

.frontier-world-list li {
  padding: 0;
}

.frontier-world-select {
  display: flex;
  width: 100%;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 10px 11px;
  border: 1px solid transparent;
  background: rgba(124, 196, 255, 0.07);
  color: #9fb4c9;
  font-size: 13px;
  text-align: left;
}

.frontier-world-select strong {
  color: #dcecff;
}

.frontier-world-list .is-undiscovered .frontier-world-select {
  opacity: 0.62;
}

.frontier-world-select[aria-pressed="true"],
.frontier-world-list .is-colonized .frontier-world-select {
  border-color: rgba(124, 196, 255, 0.48);
  background: rgba(124, 196, 255, 0.12);
}

.frontier-world-list .is-colonized .frontier-world-select {
  border-color: rgba(93, 190, 145, 0.35);
  background: rgba(93, 190, 145, 0.13);
}

.frontier-log-heading span {
  color: #82d9b1;
  font-size: 12px;
}

.frontier-log {
  max-height: 235px;
  overflow-y: auto;
}

.frontier-log li {
  padding: 8px 10px;
  border-left: 2px solid #4ba3f2;
  background: rgba(124, 196, 255, 0.06);
  color: #b7c9dc;
  font-size: 13px;
  line-height: 1.5;
}

.frontier-outcome {
  padding: 16px;
  margin: 16px 0 0;
  border: 1px solid rgba(235, 107, 98, 0.4);
  border-radius: 10px;
  background: rgba(235, 107, 98, 0.1);
  color: #ffc1b7;
  font-weight: bold;
}

.frontier-outcome.is-victory {
  border-color: rgba(93, 190, 145, 0.45);
  background: rgba(93, 190, 145, 0.1);
  color: #a7ebc8;
}

@media (max-width: 640px) {
  .frontier-game-heading,
  .frontier-log-heading {
    align-items: flex-start;
    flex-direction: column;
  }

  .frontier-stats {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .frontier-world-list li {
    min-width: 0;
  }

  .frontier-map-heading {
    align-items: flex-start;
    flex-direction: column;
  }

  .frontier-starmap {
    min-height: 170px;
  }

  .frontier-command-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  button.frontier-command {
    min-height: 76px;
  }
}

@media (max-width: 640px) {
  body {
    background-attachment: scroll;
  }

  .home-page {
    background-attachment: scroll;
  }

  .transit-page {
    background-attachment: scroll;
  }

  .page-image-credit {
    text-align: left;
  }
}

.home-page main {
  width: min(1080px, 90%);
  margin: 0 auto;
}

.home-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 28px 0;
  border-bottom: 1px solid rgba(183, 201, 220, 0.14);
}

.home-brand {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  color: #eef5ff;
  font-size: 17px;
  font-weight: bold;
  text-decoration: none;
}

.brand-symbol {
  color: #7cc4ff;
  font-size: 25px;
}

.home-header button {
  padding: 9px 14px;
  border: 1px solid #52718e;
  background: #122238;
  color: #eef5ff;
}

.home-header button:hover {
  background: #1a3452;
}

.home-hero {
  max-width: 760px;
  padding: 76px 0 64px;
}

.eyebrow {
  margin: 0 0 14px;
  color: #7cc4ff;
  font-size: 12px;
  font-weight: bold;
  letter-spacing: 0.13em;
  text-transform: uppercase;
}

.home-hero h1 {
  max-width: 700px;
  margin: 0;
  color: #eef5ff;
  font-size: clamp(38px, 7vw, 66px);
  letter-spacing: -0.045em;
  line-height: 1.08;
}

.home-intro {
  max-width: 600px;
  margin: 22px 0 0;
  font-size: 18px;
  line-height: 1.7;
}

.module-section {
  padding-bottom: 70px;
}

.section-heading {
  display: flex;
  align-items: end;
  justify-content: space-between;
  gap: 20px;
  margin-bottom: 20px;
}

.section-heading .eyebrow {
  margin-bottom: 8px;
}

.section-heading h2 {
  margin: 0;
  color: #eef5ff;
  font-size: 26px;
}

.module-count {
  padding-bottom: 4px;
  color: #8fa7bf;
  font-size: 13px;
}

.module-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(min(100%, 280px), 1fr));
  gap: 18px;
}

.module-card {
  display: flex;
  min-height: 300px;
  flex-direction: column;
  align-items: flex-start;
  padding: 26px;
  border: 1px solid rgba(124, 196, 255, 0.2);
  border-radius: 14px;
  background: linear-gradient(145deg, rgba(18, 34, 56, 0.96), rgba(13, 25, 42, 0.96));
  color: #eef5ff;
}

a.module-card {
  text-decoration: none;
  transition: transform 160ms ease, border-color 160ms ease, background-color 160ms ease;
}

a.module-card:hover,
a.module-card:focus-visible {
  transform: translateY(-4px);
  border-color: #7cc4ff;
  outline: none;
}

.module-card-upcoming {
  border-color: rgba(137, 176, 211, 0.14);
  background: linear-gradient(145deg, rgba(15, 28, 45, 0.9), rgba(11, 21, 35, 0.9));
}

.module-card-top {
  display: flex;
  width: 100%;
  align-items: center;
  justify-content: space-between;
}

.module-icon {
  display: grid;
  width: 48px;
  height: 48px;
  place-items: center;
  border-radius: 12px;
  font-size: 30px;
}

.transit-icon {
  background: rgba(75, 163, 242, 0.16);
  color: #7cc4ff;
}

.solar-icon {
  background: rgba(242, 177, 88, 0.12);
  color: #f2b158;
}

.star-evolution-icon {
  background: rgba(242, 177, 88, 0.12);
  color: #f2c878;
}

.gravity-icon {
  background: rgba(124, 196, 255, 0.12);
  color: #8bcaff;
}

.spectra-icon {
  background: rgba(178, 145, 255, 0.14);
  color: #c1a9ff;
}

.moon-icon {
  background: rgba(182, 197, 218, 0.12);
  color: #d8deea;
}

.frontier-icon {
  background: rgba(178, 145, 255, 0.14);
  color: #c1a9ff;
}

.binary-icon {
  background: rgba(124, 196, 255, 0.14);
  color: #9ed8ff;
}

.module-status {
  font-size: 11px;
  font-weight: bold;
  letter-spacing: 0.08em;
}

.status-available {
  color: #82d9b1;
}

.status-upcoming {
  color: #f2b158;
}

.module-number {
  margin: 25px 0 8px;
  color: #8fa7bf;
  font-size: 11px;
  font-weight: bold;
  letter-spacing: 0.12em;
}

.module-card h3 {
  margin: 0;
  font-size: 22px;
}

.module-description {
  margin: 11px 0 20px;
  color: #b7c9dc;
  font-size: 15px;
  line-height: 1.6;
}

.module-action {
  display: inline-flex;
  gap: 8px;
  align-items: center;
  margin-top: auto;
  color: #7cc4ff;
  font-size: 14px;
  font-weight: bold;
}

.module-action-muted {
  color: #8fa7bf;
}

.home-footer {
  padding: 22px 0 30px;
  border-top: 1px solid rgba(183, 201, 220, 0.14);
  color: #8fa7bf;
  font-size: 13px;
  text-align: center;
}

@media (max-width: 640px) {
  .home-page main {
    width: min(100% - 32px, 480px);
  }

  .home-header {
    padding: 18px 0;
  }

  .home-hero {
    padding: 58px 0 44px;
  }

  .home-intro {
    font-size: 16px;
  }

  .section-heading {
    align-items: flex-start;
    flex-direction: column;
    gap: 8px;
  }

  .module-grid {
    grid-template-columns: 1fr;
  }

  .module-card {
    min-height: 270px;
    padding: 22px;
  }

  .top-bar {
    align-items: flex-start;
    flex-direction: column;
  }

  .top-actions {
    align-self: stretch;
    justify-content: space-between;
  }
}

/* Original handheld LCD RPG presentation for Silent Frontier. */
body.frontier-page {
  background: radial-gradient(ellipse at top, #28402c 0, #142419 52%, #0b130d 100%);
  background-attachment: fixed;
  color: #d4e5b2;
  font-family: "Courier New", Courier, monospace;
}

.frontier-page .frontier-console {
  width: min(900px, calc(100% - 28px));
  margin: 18px auto 30px;
  font-family: "Courier New", Courier, monospace;
}

.frontier-page .top-bar h1 {
  color: #d8e8b8;
  font-family: inherit;
  font-size: clamp(22px, 4vw, 34px);
  letter-spacing: 0.06em;
  text-shadow: 2px 2px 0 #203626;
}

.frontier-page .top-bar p,
.frontier-page .solar-intro,
.frontier-page .solar-intro p {
  color: #abc293;
  font-family: inherit;
  line-height: 1.55;
}

.frontier-page .back-home {
  color: #d8e8b8;
  font-family: inherit;
}

.frontier-page .solar-intro {
  max-width: 900px;
  margin: 16px 0;
  padding: 12px 14px;
  border: 2px solid #425d3d;
  background: #18291c;
}

.frontier-page .solar-intro h2,
.frontier-page .frontier-game-heading h2 {
  color: #e0edc0;
  font-family: inherit;
}

.frontier-page .solar-intro .eyebrow,
.frontier-page .frontier-game .eyebrow {
  color: #9cbb76;
  font-family: inherit;
}

.frontier-page .frontier-game.solar-panel {
  margin: 12px 0;
  padding: 12px;
  border: 4px double #526b43;
  border-radius: 8px;
  background: #18291c;
  box-shadow: 0 8px 30px rgba(0, 0, 0, 0.32), inset 0 0 0 2px #0e1a12;
  color: #d4e5b2;
  font-family: inherit;
}

.frontier-page .section-description {
  color: #abc293;
  font-family: inherit;
}

.frontier-page .frontier-stats {
  gap: 4px;
  margin: 12px 0;
  padding: 7px;
  border: 2px solid #526b43;
  background: #adbd8e;
}

.frontier-page .frontier-stat {
  min-height: 54px;
  gap: 4px;
  padding: 6px;
  border: 1px solid #78895d;
  border-radius: 0;
  background: #c6d3a7;
  color: #293d29;
  font-family: inherit;
  font-size: 11px;
}

.frontier-page .frontier-stat strong {
  color: #17291d;
  font-family: inherit;
  font-size: 18px;
}

.frontier-page .frontier-meter-group {
  gap: 5px 10px;
  padding: 8px;
  margin-bottom: 10px;
  border: 2px solid #526b43;
  background: #adbd8e;
}

.frontier-page .frontier-meter-heading {
  color: #293d29;
  font-family: inherit;
}

.frontier-page .frontier-meter-heading strong {
  color: #17291d;
  font-family: inherit;
}

.frontier-page .frontier-meter {
  height: 8px;
  border: 1px solid #78895d;
  border-radius: 0;
  background: #87966b;
}

.frontier-page .frontier-meter span {
  border-radius: 0;
  background: repeating-linear-gradient(90deg, #294a31 0 8px, #91a86d 8px 10px);
}

.frontier-page .frontier-pressure span {
  background: repeating-linear-gradient(90deg, #8c6438 0 8px, #c5a16a 8px 10px);
}

.frontier-page .frontier-map-panel,
.frontier-page .frontier-log-panel {
  padding: 9px;
  border: 3px double #718257;
  border-radius: 4px;
  background: #aebd8f;
  color: #263a28;
  font-family: inherit;
}

.frontier-page .frontier-map-heading h3,
.frontier-page .frontier-log-heading h3 {
  color: #203523;
  font-family: inherit;
  letter-spacing: 0.04em;
  text-transform: uppercase;
}

.frontier-page .frontier-map-heading > span,
.frontier-page .frontier-map-heading strong {
  color: #34492e;
  font-family: inherit;
}

.frontier-page .frontier-map-viewport {
  width: min(100%, 760px);
  margin: 8px auto 0;
  border: 3px solid #4e6540;
  border-radius: 2px;
  background: #b9c99a;
  box-shadow: inset 0 0 18px rgba(34, 55, 32, 0.22);
}

.frontier-page .frontier-starmap {
  max-height: 370px;
  image-rendering: pixelated;
}

.frontier-page .frontier-starmap .starmap-background {
  fill: #b9c99a !important;
}

.frontier-page .frontier-starmap .starmap-stars circle {
  fill: #506447 !important;
  opacity: 0.72;
}

.frontier-page .frontier-starmap .starmap-routes path:not(.target-route):not(.swarm-route) {
  stroke: #89986f !important;
  stroke-dasharray: 2 7;
  stroke-width: 2;
}

.frontier-page .frontier-starmap .target-route {
  stroke: #314e38 !important;
  stroke-width: 3;
}

.frontier-page .frontier-starmap .swarm-route {
  stroke: #8b5f3e !important;
  stroke-width: 2;
}

.frontier-page .frontier-starmap .world-target-ring {
  fill: rgba(73, 100, 54, 0.12) !important;
  stroke: transparent !important;
}

.frontier-page .frontier-starmap .frontier-world-node.is-selected .world-target-ring,
.frontier-page .frontier-starmap .frontier-world-node:focus-visible .world-target-ring {
  fill: rgba(73, 100, 54, 0.26) !important;
  stroke: #334d35 !important;
}

.frontier-page .frontier-starmap .world-orbit {
  stroke: #71855a !important;
}

.frontier-page .frontier-starmap .world-body {
  stroke: #eff0c8 !important;
  stroke-width: 2;
}

.frontier-page .frontier-starmap .world-ice { fill: #dbe4bf !important; }
.frontier-page .frontier-starmap .world-rock { fill: #ba8861 !important; }
.frontier-page .frontier-starmap .world-ocean { fill: #709b83 !important; }
