const fs = require("node:fs");
const vm = require("node:vm");
const source = fs.readFileSync("/Users/zzhao08/localRepo/universe/web/app.js", "utf8");

function createPage({ noise = "0", star = "695700", planet = "6371", count = "101" } = {}) {
  const elements = new Map();
  let clears = 0;
  let draws = 0;
  const ctx = new Proxy({
    measureText: (text) => ({ width: String(text).length * 8 }),
    clearRect() { clears++; },
    fillText() {},
  }, { get(target, key) { return key in target ? target[key] : () => { draws++; }; } });
  const getElementById = (id) => {
    if (!elements.has(id)) {
      elements.set(id, {
        id,
        value: id === "star-radius" ? star :
          id === "planet-radius" ? planet :
          id === "noise-level" || id === "noise-number" ? noise :
          id === "observation-count" ? count : "",
        textContent: "",
        innerHTML: "",
        width: 800,
        height: 500,
        listeners: {},
        attributes: {},
        addEventListener(type, fn) { this.listeners[type] = fn; },
        setAttribute(name, value) { this.attributes[name] = value; },
        getContext() { return ctx; },
      });
    }
    return elements.get(id);
  };
  const document = {
    documentElement: { lang: "" },
    title: "",
    getElementById,
    querySelectorAll: () => [],
  };
  const storage = { value: "en", getItem() { return this.value; }, setItem(_, value) { this.value = value; } };
  const math = Object.create(Math);
  math.random = () => 0.5;
  vm.runInNewContext(source, { document, localStorage: storage, Math: math, Number });
  return { elements, storage, get: getElementById, get clears() { return clears; }, get draws() { return draws; } };
}

const exact = createPage({ noise: "0" });
exact.get("simulate-button").listeners.click();
const exactRadius = Number(exact.get("results").innerHTML.match(/Planet radius estimated from noisy observations \(km\): ([0-9.]+)/)?.[1]);
if (!Number.isFinite(exactRadius) || Math.abs(exactRadius - 6371) > 0.01) {
  throw new Error(`Zero-noise fit should recover input radius, got ${exactRadius}`);
}
console.log("zero-noise fit recovers input radius: passed");

const noisy = createPage({ noise: "50", star: "695700", planet: "6371", count: "87" });
noisy.get("simulate-button").listeners.click();
const originalResults = noisy.get("results").innerHTML;
const estimatedRadius = Number(originalResults.match(/Planet radius estimated from noisy observations \(km\): ([0-9.]+)/)?.[1]);
if (!Number.isFinite(estimatedRadius) || estimatedRadius === 6371) {
  throw new Error(`Noisy-data estimate did not respond to sampled noise: ${estimatedRadius}`);
}
if (!originalResults.includes("Transit depth fitted to noisy observations")) throw new Error("Fitted depth is not separately reported");
const originalDraws = noisy.draws;
noisy.get("language-button").listeners.click();
if (Number(noisy.get("star-radius").value) !== 695700 || Number(noisy.get("planet-radius").value) !== 6371 || Number(noisy.get("noise-number").value) !== 50 || Number(noisy.get("observation-count").value) !== 87) {
  throw new Error("Language change reset current inputs");
}
if (!noisy.get("results").innerHTML.includes("根据带噪声观测估算的行星半径")) {
  throw new Error("Results were not translated after language change");
}
const localizedRadius = Number(noisy.get("results").innerHTML.match(/根据带噪声观测估算的行星半径（公里）: ([0-9.]+)/)?.[1]);
if (localizedRadius !== estimatedRadius) throw new Error("Language change changed the estimated radius");
if (!noisy.get("chart-summary").textContent.includes("观测点数: 87") || noisy.draws <= originalDraws) {
  throw new Error("Chart was not preserved/redrawn with localized accessible summary");
}
console.log("noise-based fit and input/result/chart retention on language toggle: passed");

const fs = require("node:fs");
const vm = require("node:vm");

const source = fs.readFileSync("/Users/zzhao08/localRepo/universe/web/app.js", "utf8");

function simulate(values = {}) {
  const elements = new Map();
  const getElementById = (id) => {
    if (!elements.has(id)) {
      const element = {
        id,
        value: "",
        textContent: "",
        innerHTML: "",
        listeners: {},
        addEventListener(type, callback) { this.listeners[type] = callback; },
        setAttribute() {},
      };
      elements.set(id, element);
    }
    return elements.get(id);
  };
  const context2d = new Proxy({ measureText: (text) => ({ width: String(text).length * 7 }) }, {
    get(target, key) {
      if (key in target) return target[key];
      return () => {};
    },
  });
  const canvas = getElementById("light-curve");
  canvas.width = 800;
  canvas.height = 460;
  canvas.getContext = () => context2d;
  Object.assign(getElementById("star-radius"), { value: "695700" }, values.starRadius && { value: values.starRadius });
  Object.assign(getElementById("planet-radius"), { value: "6371" }, values.planetRadius && { value: values.planetRadius });
  Object.assign(getElementById("noise-number"), { value: Object.hasOwn(values, "noise") ? values.noise : "50" });
  Object.assign(getElementById("noise-level"), { value: "50" });
  Object.assign(getElementById("observation-count"), { value: "101" }, values.observationCount && { value: values.observationCount });
  const document = {
    documentElement: { lang: "en" },
    title: "",
    getElementById,
    querySelectorAll: () => [],
  };
  const sandbox = {
    document,
    localStorage: { getItem: () => "en", setItem() {} },
    Math,
    Number,
    console,
  };
  vm.runInNewContext(source, sandbox);
  if (Object.hasOwn(values, "noise")) {
    getElementById("noise-number").value = values.noise;
  }
  getElementById("simulate-button").listeners.click();
  return { elements, context2d };
}

function expectError(label, values, expected) {
  const { elements } = simulate(values);
  const message = elements.get("results").textContent;
  if (!message.includes(expected)) throw new Error(`${label}: expected ${expected}, got ${message}`);
  console.log(`${label}: passed`);
}

const normal = simulate();
if (!normal.elements.get("simulation-status").textContent.includes("complete")) throw new Error("normal simulation did not complete");
if (!normal.elements.get("chart-summary").textContent.includes("101")) throw new Error("chart summary missing observation count");
console.log("normal simulation and accessible summary: passed");
expectError("non-finite star radius", { starRadius: "Infinity" }, "greater than zero");
expectError("planet larger than star", { starRadius: "10", planetRadius: "11" }, "cannot be larger");
expectError("empty noise", { noise: "" }, "valid noise value");
expectError("too few observations", { observationCount: "1" }, "between 2 and 1000");
const noiseless = simulate({ noise: "0" });
if (!noiseless.elements.get("results").innerHTML.includes("∞")) throw new Error("zero-noise SNR boundary failed");
console.log("zero-noise boundary: passed");

const fs = require("fs");
const vm = require("vm");
const ids = ["language-button", "system-type", "system-preset", "play-toggle", "reset-button", "speed-control", "speed-value", "star-canvas", "star-legend", "elapsed-time", "total-mass", "canvas-description"];
const noop = () => {};
const ctx = new Proxy({ createRadialGradient: () => ({ addColorStop: noop }), setTransform: noop }, {
  get: (target, key) => target[key] || noop,
  set: (target, key, value) => (target[key] = value, true)
});
const elements = Object.fromEntries(ids.map((id) => {
  const element = { id, dataset: {}, listeners: {}, clientWidth: 900, clientHeight: 540, textContent: "", options: [], classList: { toggle: noop },
    addEventListener(type, fn) { this.listeners[type] = fn; }, setAttribute: noop,
    getContext: () => ctx };
  let value = id === "system-type" ? "binary" : id === "system-preset" ? "equalBinary" : id === "speed-control" ? "1" : "";
  Object.defineProperty(element, "value", { get: () => value, set: (next) => { value = next; } });
  Object.defineProperty(element, "innerHTML", { get: () => element._html || "", set: (html) => {
    element._html = html;
    const values = [...html.matchAll(/<option value="([^"]+)"/g)].map((match) => match[1]);
    if (values.length) { element.options = values; if (!values.includes(value)) value = values[0]; }
  }});
  return [id, element];
}));
let nextFrame;
const document = { title: "", documentElement: { lang: "" }, getElementById: (id) => elements[id], querySelectorAll: () => [] };
const sandbox = { document, localStorage: { getItem: () => null, setItem: noop }, Math, Number, String,
  window: { matchMedia: () => ({ matches: false }), requestAnimationFrame: (fn) => { nextFrame = fn; }, addEventListener: noop, devicePixelRatio: 1 } };
vm.runInNewContext(fs.readFileSync("web/binary-triple-system.js", "utf8"), sandbox);
nextFrame(0); nextFrame(16); nextFrame(80);
if (!elements["star-legend"].innerHTML.includes("Star 2")) throw Error("Binary did not initialize");
elements["system-type"].value = "triple"; elements["system-type"].listeners.change();
if (!elements["star-legend"].innerHTML.includes("Star 3")) throw Error("Triple system did not initialize");
elements["system-preset"].value = "hierarchicalTriple"; elements["system-preset"].listeners.change();
if (elements["total-mass"].textContent !== "2.15") throw Error("Hierarchical triple stats are incorrect");
elements["language-button"].listeners.click();
if (document.documentElement.lang !== "zh") throw Error("Language toggle failed");
console.log("Simulation smoke test passed: binary, triple, hierarchical preset, animation, and language toggle.");

const fs = require("fs");
const vm = require("vm");
const ids = ["language-button", "system-type", "system-preset", "play-toggle", "reset-button", "speed-control", "speed-value", "show-gravity-vectors", "star-canvas", "star-legend", "elapsed-time", "total-mass", "canvas-description"];
const calls = { lineTo: 0 };
const ctx = new Proxy({ createRadialGradient: () => ({ addColorStop() {} }), setTransform() {}, lineTo() { calls.lineTo += 1; } }, {
  get: (target, key) => target[key] || (() => {}),
  set: (target, key, value) => (target[key] = value, true)
});
const elements = Object.fromEntries(ids.map((id) => {
  const el = { id, dataset: {}, listeners: {}, clientWidth: 900, clientHeight: 540, textContent: "", checked: true, classList: { toggle() {} }, addEventListener(type, fn) { this.listeners[type] = fn; }, setAttribute() {}, getContext: () => ctx };
  let value = id === "system-type" ? "binary" : id === "system-preset" ? "equalBinary" : id === "speed-control" ? "1" : "";
  Object.defineProperty(el, "value", { get: () => value, set: (v) => { value = v; } });
  Object.defineProperty(el, "innerHTML", { get: () => el._html || "", set: (html) => { el._html = html; const opts = [...html.matchAll(/<option value="([^"]+)"/g)].map((m) => m[1]); if (opts.length && !opts.includes(value)) value = opts[0]; } });
  return [id, el];
}));
let raf;
const sandbox = { Math, Number, String, document: { title: "", documentElement: { lang: "" }, getElementById: (id) => elements[id], querySelectorAll: () => [] }, localStorage: { getItem: () => null, setItem() {} }, window: { matchMedia: () => ({ matches: false }), requestAnimationFrame: (fn) => { raf = fn; }, addEventListener() {}, devicePixelRatio: 1 } };
vm.runInNewContext(fs.readFileSync("web/binary-triple-system.js", "utf8"), sandbox);
const withVectors = calls.lineTo;
elements["show-gravity-vectors"].checked = false;
elements["show-gravity-vectors"].listeners.change();
const withoutVectors = calls.lineTo - withVectors;
if (withoutVectors >= withVectors) throw Error("Disabling vectors did not hide acceleration arrows");
elements["system-type"].value = "triple"; elements["system-type"].listeners.change();
if (!elements["star-legend"].innerHTML.includes("Star 3")) throw Error("Triple system did not initialize");
console.log("Gravity-vector smoke test passed: arrows render, toggle hides them, and triple preset initializes.");

const fs = require("fs");
const vm = require("vm");
const ids = ["language-button", "system-type", "system-preset", "play-toggle", "reset-button", "speed-control", "speed-value", "show-gravity-vectors", "mass-controls", "star-canvas", "star-legend", "elapsed-time", "total-mass", "canvas-description"];
const noop = () => {};
const ctx = new Proxy({ createRadialGradient: () => ({ addColorStop: noop }), setTransform: noop }, { get: (target, key) => target[key] || noop, set: (target, key, value) => (target[key] = value, true) });
const elements = Object.fromEntries(ids.map((id) => {
  const el = { id, dataset: {}, listeners: {}, clientWidth: 900, clientHeight: 540, textContent: "", checked: true, classList: { toggle: noop }, addEventListener(type, fn) { this.listeners[type] = fn; }, setAttribute: noop, getContext: () => ctx };
  let value = id === "system-type" ? "binary" : id === "system-preset" ? "equalBinary" : id === "speed-control" ? "1" : "";
  Object.defineProperty(el, "value", { get: () => value, set: (v) => { value = v; } });
  Object.defineProperty(el, "innerHTML", { get: () => el._html || "", set: (html) => {
    el._html = html;
    const options = [...html.matchAll(/<option value="([^"]+)"/g)].map((m) => m[1]);
    if (options.length && !options.includes(value)) value = options[0];
    for (const match of html.matchAll(/<output id="([^"]+)"[^>]*>([^<]*)<\/output>/g)) {
      elements[match[1]] ||= { textContent: match[2] };
    }
  }});
  return [id, el];
}));
let raf;
const document = { title: "", documentElement: { lang: "" }, getElementById: (id) => elements[id] || (elements[id] = { textContent: "" }), querySelectorAll: () => [] };
const sandbox = { Math, Number, String, document, localStorage: { getItem: () => null, setItem: noop }, window: { matchMedia: () => ({ matches: false }), requestAnimationFrame: (fn) => { raf = fn; }, addEventListener: noop, devicePixelRatio: 1 } };
vm.runInNewContext(fs.readFileSync("web/binary-triple-system.js", "utf8"), sandbox);
if (!elements["mass-controls"].innerHTML.includes("mass-slider-1")) throw Error("Binary mass sliders were not rendered");
const slider = { dataset: { starIndex: "0" }, value: "1.75", closest: () => slider };
elements["mass-controls"].listeners.input({ target: slider });
if (elements["mass-value-0"].textContent !== "1.75 M") throw Error("Mass output did not update");
if (!elements["star-legend"].innerHTML.includes("1.75 M") || elements["total-mass"].textContent !== "2.75") throw Error("Mass change did not update simulation UI");
elements["system-type"].value = "triple"; elements["system-type"].listeners.change();
if (!elements["mass-controls"].innerHTML.includes("mass-slider-2")) throw Error("Triple mass sliders were not rendered");
console.log("Mass-slider smoke test passed: mass change updates output, legend, total, and triple controls.");

import math

def setup(kind):
    if kind == "equal":
        masses=[1,1]; sep=1.4; total=sum(masses); rel=math.sqrt(total/sep)
        return masses,[(-masses[1]*sep/total,0,0,-masses[1]*rel/total),(masses[0]*sep/total,0,0,masses[0]*rel/total)]
    if kind == "unequal":
        masses=[1.4,.45]; sep=1.6; total=sum(masses); rel=math.sqrt(total/sep)
        return masses,[(-masses[1]*sep/total,0,0,-masses[1]*rel/total),(masses[0]*sep/total,0,0,masses[0]*rel/total)]
    if kind == "figure8":
        masses=[1,1,1]
        return masses,[(-.97000436,.24308753,.466203685,.43236573),(.97000436,-.24308753,.466203685,.43236573),(0,0,-.93240737,-.86473146)]
    masses=[1,.8,.35]; inner=sum(masses[:2]); outer=masses[2]; radius=1.75; sep=.72
    icx=-outer*radius/(inner+outer); ox=inner*radius/(inner+outer)
    iv=math.sqrt(inner/sep); ov=math.sqrt((inner+outer)/radius)
    icy=-outer*ov/(inner+outer); oy=inner*ov/(inner+outer)
    return masses,[(icx-masses[1]*sep/inner,0,0,icy-masses[1]*iv/inner),(icx+masses[0]*sep/inner,0,0,icy+masses[0]*iv/inner),(ox,0,0,oy)]

def deriv(masses,s):
    a=[[0.,0.] for _ in s]
    for i in range(len(s)):
        for j in range(i+1,len(s)):
            dx=s[j][0]-s[i][0]; dy=s[j][1]-s[i][1]; q=dx*dx+dy*dy+0.0001; inv=1/(q*math.sqrt(q))
            a[i][0]+=masses[j]*dx*inv; a[i][1]+=masses[j]*dy*inv
            a[j][0]-=masses[i]*dx*inv; a[j][1]-=masses[i]*dy*inv
    return [(b[2],b[3],a[i][0],a[i][1]) for i,b in enumerate(s)]
def add(s,k,f): return [tuple(x+f*y for x,y in zip(b,d)) for b,d in zip(s,k)]
def energy(m,s):
    e=sum(.5*mi*(b[2]**2+b[3]**2) for mi,b in zip(m,s))
    for i in range(len(s)):
        for j in range(i+1,len(s)):
            r=math.sqrt((s[j][0]-s[i][0])**2+(s[j][1]-s[i][1])**2+0.0001)
            e-=m[i]*m[j]/r
    return e
def momentum(m,s): return (sum(mi*b[2] for mi,b in zip(m,s)),sum(mi*b[3] for mi,b in zip(m,s)))
for name in ("equal","unequal","figure8","hierarchical"):
    masses,state=setup(name); e0=energy(masses,state); p0=momentum(masses,state); maxde=0
    for n in range(25000):
        dt=.004; k1=deriv(masses,state); k2=deriv(masses,add(state,k1,dt/2)); k3=deriv(masses,add(state,k2,dt/2)); k4=deriv(masses,add(state,k3,dt))
        state=[tuple(x+dt*(a+2*b+2*c+d)/6 for x,a,b,c,d in zip(s,k1[i],k2[i],k3[i],k4[i])) for i,s in enumerate(state)]
        if n%100==0: maxde=max(maxde,abs((energy(masses,state)-e0)/e0))
    px,py=momentum(masses,state)
    print(f"{name}: E0={e0:.6f}, max relative energy drift={maxde:.3e}, final linear momentum=({px:.3e}, {py:.3e}), COM={tuple(round(sum(masses[i]*state[i][k] for i in range(len(masses)))/sum(masses), 4) for k in (0,1))}")
